quests[33373] = { id = 33373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "5.4 Raid - RRP - Boss 14 Legendary Quest" }
quests[33374] = { id = 33374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Nebelgängers", description = "Ihr habt vernommen, was die Erhabenen gesagt haben, aber was habt Ihr auf Eurem Weg zu den Schreinen gelernt?\n\nDie Weisheit einer Pilgerreise offenbart sich in ihrer Stille und Einfachheit. Während Ihr dem Wind in den Bäumen lauscht und den Flug selbst des kleinsten Schmetterlings beobachtet, öffnet sich Euer Geist, um die tiefgründigsten Lektionen zu erfahren, die die Prüfungen uns lehren können. Habt Ihr die vielen großen Kreaturen gesehen, die auf der Insel ihre Kreise ziehen?\n\nDas ist Eure Prüfung. Pandaria hat Euch viel beigebracht. Jetzt werden wir das Gelernte auf die Probe stellen.", sourceObjective = "Vernichtet 20 Elitekreaturen auf der Zeitlosen Insel.", progress = "Haben die Lektionen Pandarias Euch auf Eurer Reise geholfen?", completion = "Dies soll Eure tägliche Lektion sein. Möge sie Eure Kraft, Weisheit und Tapferkeit stärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[33375] = { id = 33375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vision genauer bestimmen", description = "Ich habe die Steine zermahlen und das Stundenglas auf eine neue Reihe von Zeitlinien eingestellt. Würdet Ihr noch einmal zur Schlacht um Orgrimmar zurückkehren und das Stundenglas erneut drehen?\n\nBeeilt Euch bitte, ich bin zutiefst neugierig.", sourceObjective = "Verwendet die Vision der Zeit in der Schlacht um Orgrimmar.", completion = "Eine wahre Heldentat und ein mächtiger Moment in der Geschichte. Aber nicht ganz das, was wir gesucht haben, befürchte ich.\n\nEs bleibt nicht mehr viel Zeit – ich werde meine Bemühungen verdoppeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[33376] = { id = 33376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Bestimmung", description = "Ich muss gestehen, dass ich Euch gegenüber nicht ganz ehrlich war, trotz allem, was Ihr für die Zeitwanderer getan habt. Ich kann Euch nicht alles sagen, noch nicht, aber Ihr solltet wissen, dass es einen Verräter unter uns gibt. Sprecht mit niemandem über Eure heutige Mission und seid vorsichtig, wenn Ihr in der Nähe von Mitgliedern meines Schwarms seid, während Ihr die Vision der Zeit bei Euch tragt.\n\nJetzt beeilt Euch und kehrt noch einmal zur Schlacht um Orgrimmar zurück und setzt das Stundenglas ein.\n\nUnd passt auf Euch auf.", sourceObjective = "Verwendet die Vision der Zeit in der Schlacht um Orgrimmar.", completion = "War das etwa... ich? Wie interessant.\n\nSo langsam können wir den Schatten zwischen den Welten wahrnehmen. War dies die Zukunft unserer Welt oder einfach nur eine von viele Möglichkeiten? Wie dem auch sein mag – unsere neuerworbene Fähigkeit, tiefer in die Zeitlinien hineinzublicken wird uns dabei helfen, die Antworten zu finden, nach denen wir suchen.\n\nGebt mir ein wenig mehr Zeit, um meine Forschungen fortzuführen. Und seid wachsam, Held, denn die Anzahl der Zeitlinien ist genauso endlos wie die unserer Feinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[33377] = { id = 33377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Stränge", description = "Ihr habt unsere Mission geheim gehalten und dafür möchte ich Euch danken. Wenn das Wissen um die Zeitlinien in die falschen Hände gerät, kann dies katastrophale Folgen haben. Mein Schwarm ist nicht mehr in der Lage, diese abzufedern. Wir müssen vorsichtig sein.\n\nDas Stundenglas wird mächtiger. Ich glaube, dass man mit ihm jetzt viel weiter als zuvor blicken kann. Ich möchte, dass Ihr seine Grenzen ausreizt.\n\nKehrt zurück zur Schlacht um Orgrimmar und fokussiert das Stundenglas auf die zerstörerischste Zeitlinie, die Ihr finden könnt.", sourceObjective = "Verwendet die Vision der Zeit in der Schlacht um Orgrimmar.", completion = "Sturmwind... zerstört?\n\nIch verstehe, dass diese Vision Euch schockieren mag. Zu diesem Zeitpunkt weiß ich kaum mehr als Ihr. Ich verspreche Euch, alles zu tun, um Antworten zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33378] = { id = 33378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal herausfordern", description = "Die Vision der Zeit ist fast vollendet und wir haben jetzt viel mehr Kontrolle über die Visionen, die wir sehen möchten. Eure Bemühungen waren von entscheidender Bedeutung bei der Vervollständigung des Artefakts und dem erneuten Erstarken meines Schwarms und unserer Verbündeten, der Zeitwanderer. Wir alle stehen in Eurer Schuld.\n\nEin glücklicher Zufall will es, dass ich eine Art Schlüsselstelle in der Zeit gefunden habe – eine Kreuzung von verschiedenen Zeitlinien – und zwar hier in Pandaria. Bringt die Vision der Zeit zum Tempel des Weißen Tigers. Dreht das Stundenglas, sobald Ihr in den Kellern dort seid.", sourceObjective = "Verwendet die Vision der Zeit im Tempel des Weißen Tigers auf dem Kun-Lai-Gipfel.", completion = "Ah, es scheint, als ob unserem kleinen Prinzen noch eine Aufgabe zufallen wird. Wir sollten kein weiteres Wort darüber verlieren, um nicht Gefahr zu laufen, selbst die Zukunft zu verändern.\n\nDer Wald hat Ohren, Held. Sprecht mit niemandem hierüber. Mit der Zeit werden wir unsere Antworten schon finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33379] = { id = 33379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Mal", description = "Ich möchte Euch eigentlich nicht erneut um etwas bitten müssen, doch weiß ich nicht mehr, wem ich noch trauen kann. Ich habe die Vision der Zeit eingesetzt, um Informationen zu sammeln, und während meiner Suche bin ich anscheinend über noch eine Schlüsselstelle in der Zeit gestolpert. Sie befindet sich in den Höhlen der Zeit selbst.\n\nAls ich die Vision erblickte, wollte ich es zunächst nicht wahrhaben, doch ich kann nicht einfach still dasitzen und diese Information ignorieren. Die Höhlen der Zeit – Ihr müsst Euch jetzt dorthin begeben und die Vision der Zeit einsetzen.\n\nBeeilt Euch!", sourceObjective = "Verwendet die Vision der Zeit in den Höhlen der Zeit in Tanaris.", completion = "Soridormi, die Hauptgefährtin Nozdormus, tot? Und ich war auch dort?\n\nWir können nicht wissen, was das bedeutet, was passieren wird oder ob diese Vision überhaupt in unserer Zeitlinie eintreten wird. Ihr dürft mit niemandem über diese Vision sprechen, sonst könnten wir den Verlauf der Zeit ändern und so große Gefahr für uns alle heraufbeschwören. Alles, was uns jetzt zu tun bleibt, ist, die Vision der Zeit abzuschließen – nur sie wird uns einen wahren Ausblick auf die Zukunft ermöglichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33380] = { id = 33380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
