quests[33389] = { id = 33389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Yggdrel der Verderbte" }
quests[33398] = { id = 33398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "South Sprint Practice", description = "Hier gilt: Rennt durch den Bogen, erreicht die rote Markierung, dann die violette Markierung und kehrt dann hierher zurück.\n\nIhr könnt Euch so viel Zeit nehmen, wie Ihr braucht.", sourceObjective = "Rennt durch den Bogen, erreicht die rote Markierung, dann die violette Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33407] = { id = 33407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "Mein Bruder Ga'nar hat vor ein paar Stunden mit ein paar meiner besten Leutnants ein Überfallkommando in die Zitadelle geführt. Sie sind noch nicht zurückgekehrt.\n\nIhr müsst unserer Meute vorauseilen und nach ihnen suchen. Wie brauchen jeden Krieger, wenn wir bis zum Ende des Tages den Fuß auf den Schädel des Speerspießerfürsten Gorr'thog setzen möchten.", sourceObjective = "Sucht Ga'nar, Ligra und Korga bei der Ogerfestung.", sourceObjectiveStatus = "unverified-source-field" }
quests[33408] = { id = 33408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großartige Feuerbälle!", description = "Ga'nar hat Ligra und die anderen auf die zweite Ebene der Festung geführt. Und auch Euer Freund, Thrall, ist ihnen zur Hilfe geeilt.\n\nFolgt der Rampe draußen am Südende des Bollwerks und schließt Euch ihnen an.\n\nHelft ihnen, den Sieg für den Frostwolfklan zu erringen!", sourceObjective = "Sprecht mit Thrall in der Speerspießerfestung.", completion = "Auf dem Weg hierher wurden viele verwundet oder getötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[33409] = { id = 33409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn Run" }
quests[33410] = { id = 33410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlächter der Speerspießer", description = "Nach Ga'nars Vorstoß in die Festung haben die Speerspießer eine riesige Kreatur auf unsere Truppen losgelassen.\n\nIch bin nach dem Einsatz meiner Magie immer noch geschwächt, aber zumindest kann ich dafür sorgen, dass sich dieser Orc erholt.\n\nIhr dagegen müsst dafür sorgen, dass Dorogg fällt, {name}.", sourceObjective = "Erschlagt Dorogg den Skrupellosen.", progress = "Ist Dorogg gefallen?", completion = "Dieser Raum erzitterte, als das Monster fiel. Eure Taten werden nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33412] = { id = 33412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumarbeiten", description = "Heute waren wir siegreich, aber uns bleibt hier noch viel Arbeit.\n\nDie Frostwölfe werden die Zitadelle durchsuchen und sich um alle überlebenden Feinde kümmern. Euch biete ich die glorreiche Aufgabe der Säuberung der Gladiatorgruben im Norden an.\n\nAls wir unseren Angriff begonnen haben, habe ich eine meiner Besten ausgesandt, um das Gebiet auszukundschaften. Wenn es Euch weiterhin nach Blut dürstet, dann trefft Euch mit ihr. Es werden sicher noch einige Gegner übrig sein.", sourceObjective = "Sprecht mit Igrimar der Entschlossenen am Zirkel des Blutes.", completion = "<Igrimar verzieht das Gesicht, als Ihr ihr Durotans Befehle zeigt.>\n\nSeht mich nicht so an... uh... Ich habe Schlimmeres überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[33416] = { id = 33416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "South Sprint 12", description = "Hier gilt: Rennt durch den Bogen, erreicht die rote Markierung, dann die violette Markierung und kehrt danach hierher zurück, bevor die Glocke 12-mal geschlagen hat. Viel Glück!", sourceObjective = "Rennt durch den Bogen, erreicht die rote Markierung, dann die violette Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33418] = { id = 33418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schild hoch!" }
quests[33419] = { id = 33419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es geht um Leben und Tod", description = "<Fremder/Fremde>, bitte helft mir!\n\nMeine Gefährten und ich hatten den tollkühnen Plan, eine monströse Wespenkönigin zu erlegen, um uns die Belohnung dafür zu sichern.\n\nNachdem wir unser Lager am Fuße des Hügels aufgeschlagen hatten, schliefen wir ein. Mitten in der Nacht wurden wir von diesen schrecklichen bleichen... Kreaturen angegriffen!\n\nIch habe keine Ahnung, wo meine Freunde sind, aber ich habe tiefer in der Höhle Schreie gehört.\n\nBitte findet meine Gefährten! Ich kann nicht ohne sie aufbrechen!", sourceObjective = "Findet Arekk, Diaani und Zuulo in der Blutdornhöhle.", progress = "Sie haben uns gewarnt, hierher zu kommen, aber wir wollten nicht zuhören. Warum haben wir nicht auf sie gehört!?", completion = "Meine Gebete wurden erhört, {name}. Ich werde allen im Dorf von Euren Taten berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33422] = { id = 33422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn Long Distance Practice", description = "Hier gilt: Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung und schließlich kehrt hierher zurück.\n\nhr könnt Euch dafür so viel Zeit nehmen, wie Ihr braucht.", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung und kehrt dann zum Lager der Eisengnomspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33424] = { id = 33424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northshire Dash 12", description = "Hier gilt: Rennt durch den Bogen, erreicht die blaue Markierung und kehrt danach so schnell Ihr könnt hierher zurück.\n\nSeid wieder hier, bevor die Glocke 12-mal geschlagen hat.", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33425] = { id = 33425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blue/Yellow Sprint 15 INTERNAL REPEATABLE", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33427] = { id = 33427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser ist der Zorn", description = "Wenn Drek'Thar sich erst daran gewöhnt hat, wird er keine Probleme haben. Der Elementar hat ihm eine mächtige Vision geschenkt und er ist auf dem Weg, der größte Schamane dieser Welt zu werden.\n\nIhr müsst Kriegsmeister Zog in Eurer Garnison aufsuchen und ihm berichten, was hier geschehen ist.\n\nEr kann ein paar Einheiten bereitstellen, die helfen, das Gebiet zu sichern.", sourceObjective = "Sprecht mit Kriegsmeister Zog in Eurer Garnison im Frostfeuergrat.", completion = "Gut gemacht, Kommandant. Ich werde versuchen, mehr Truppen in das Gebiet zu entsenden, um dort weiter aufzuräumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33429] = { id = 33429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn Distanzrennen: 25", description = "Hier gilt: Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung und kehrt danach hierher zurück, bevor die Glocke 25-mal geschlagen hat.", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33431] = { id = 33431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn South Distance Trial: 30", description = "Hier gilt: Rennt durch den Bogen, erreicht die rote Markierung, dann die violette Markierung und kehrt danach hierher zurück, bevor die Glocke 30-mal geschlagen hat.", sourceObjective = "Rennt durch den Bogen, erreicht die rote Markierung, dann die violette Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33432] = { id = 33432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn South Distance Practice", description = "Ihr wollt etwas üben?\n\nHier gilt: Rennt durch den Bogen, erreicht die rote Markierung, dann die violette Markierung und kehrt schließlich hierher zurück.\n\nhr könnt Euch so viel Zeit nehmen, wie Ihr braucht.", sourceObjective = "Rennt durch den Bogen, erreicht die rote Markierung, dann die violette Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33434] = { id = 33434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfall Race 30", description = "Rennt durch den Bogen...\nErreicht die blaue Markierung...\nErreicht die grüne Markierung...\nDann kehrt hierher zurück, bevor die Glocke 15-mal geschlagen hat.\n\nViel Glück!", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33438] = { id = 33438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zeitverzerrter Primalist" }
quests[33439] = { id = 33439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zeitverzerrter rennender Schläger" }
quests[33440] = { id = 33440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zeitverzerrter fallender Schläger 1" }
quests[33441] = { id = 33441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thralls Vision" }
quests[33443] = { id = 33443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörte Barriere" }
quests[33444] = { id = 33444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fressologie", description = "Drek'Thar glaubt, dass die Teile von Exurotus, die die Goren verschlungen haben, möglicherweise nutzlos sind. Ich werde aber dem Zorn nicht entgegentreten, ohne vorher so viele dieser \"Partikel\" wie möglich gesichert zu haben.\n\nTötet so viele Goren, wie Ihr in Magnarok finden könnt, und versucht, ihnen ihre Frostfeuerpartikel zu entnehmen.", sourceObjective = "Sammelt 10 Frostfeuerpartikel ein.", progress = "Konntet Ihr ein paar Partikel sichern?", completion = "Goren sind Scheusale. Sie wurden erschaffen, um die Welt zu fressen. Das habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[33447] = { id = 33447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Handwerker der Speerspießer" }
quests[33448] = { id = 33448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[33450] = { id = 33450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wache des Kriegsfürsten", description = "Ich weiß nicht, was Ihr gewohnt seid, <Reisender/Reisende>, aber dieses Land verschlingt die Schwachen. Vielleicht möchte Durotan sich Eurer entledigen. Wir werden sehen.\n\nIhr müsst den Kriegsfürsten vom Zirkel des Blutes töten. Wenn Ihr das vermögt, werden die Oger hier geschlagen sein. Doch zuerst müsst Ihr ihn finden.\n\nIch habe seine Leibwächter ganz in der Nähe aufgespürt. Tötet sie und bringt mir ihre Köpfe. Damit können wir den Kriegsherren hervorlocken.", sourceObjective = "Sammelt Rumms' Kopf, Gulloks Kopf und Splorgs Kopf.", progress = "Ihr weilt immer noch unter den Lebenden, hm?\n\nHabt Ihr Euch um die Untergebenen des Kriegsfürsten gekümmert?", completion = "Ihr habt gute Arbeit geleistet, aber werdet nicht überheblich. Dieses Land birgt Gefahren, die weitaus größer sind als das, was Ihr hier gesehen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[33454] = { id = 33454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gegenmittel", description = "Feiglinge! Verflucht seien diese erbärmlichen Fleischsäcke!\n\nDie Speerspießer haben die Orcklans immer verhöhnt, indem sie unsere Verwundeten versklavten und wie Hunde in ihren Gruben kämpfen ließen.\n\nAls Vergeltung für unseren Angriff haben sie ihre Orcgefangenen vergiftet, um sie leiden und einen qualvollen Tod sterben zu lassen.\n\nNur ihre Geomanten führen das Gegengift mit sich. Setzt es ein, um die gefangenen Frostwölfe zu heilen.", sourceObjective = "Heilt 5 Gladiatoren der Frostwölfe.", completion = "Ihr habt dem Frostwolfklan einen Dienst erwiesen. Ich werde Durotan mit Sicherheit von Euren Taten berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33456] = { id = 33456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katapultsicht" }
quests[33457] = { id = 33457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katapultsicht" }
quests[33458] = { id = 33458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katapultsicht" }
quests[33461] = { id = 33461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schummerwildjäger", description = "<Ihr findet eine auf Pergament geschriebene Liste.\n\nArsenio benötigt ein paar Zutaten für ein neues Rezept, das er in Eurer Garnison ausprobieren möchte.>", sourceObjective = "Sammelt Zutaten im Schummergehölz.", progress = "Habt Ihr alle Zutaten gefunden, die ich brauche?", completion = "Sehr schön! Danke Euch vielmals! Damit kann ich einen sehr leckeren Eintopf aus Wolfsfleisch, Froschbeinen und Pilzen machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[33462] = { id = 33462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerfürst für einen Tag", description = "Teile einer Donnerfürstenkette liegen auf dem Boden. Die Ausführung ist sehr einfach, aber effektiv.\n\nMit genug Teilen könnte auch die untalentierteste Person eine Kette mit Haken fertigen, die ähnlich effektiv ist wie die der Raufer der Donnerfürsten.", sourceObjective = "Fertigt einen Donnerfürstenhaken.", progress = "Dieser ausgediente, abgenutzte Amboss wird hauptsächlich zur Fertigung von Ketten und anderen kleineren Metallarbeiten verwendet, die die Donnerfürsten benötigen.", completion = "Ein sanfter Schlag mit dem Hammer, ein Klopfer an den Ringen und schon ist der Donnerfürstenhaken so gut wie neu.", sourceObjectiveStatus = "unverified-source-field" }
quests[33467] = { id = 33467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz des Kriegsfürsten", description = "Ihr habt Euch als ziemlich zäh erwiesen, <Fremder/Fremde>. Jetzt bleibt nur noch eins zu tun: den Kriegsfürsten der Arena zu stürzen.\n\nDas wird Eure erste richtige Prüfung hier sein. Bult wäre sogar für einen kampfgestählten Frostwolf eine Herausforderung.\n\nSteckt die von Euch gesammelten Köpfe in der Frostfeuerarena auf Spieße. Sie werden den Kriegsfürsten sicher in Raserei versetzen und ihn zum Kampf locken.\n\nKommt siegreich aus der Arena. Das wird allen beweisen, dass Durotan sein Vertrauen nicht vergebens in Euch gesetzt hat.", sourceObjective = "Tötet den Kriegsfürsten Bult.", completion = "Beeindruckende Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[33468] = { id = 33468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung für Wolfsheim", description = "Diese feigen Donnerfürsten...\n\nWährend der Schlacht um die Zitadelle haben Läufer mir mitgeteilt, dass der Eisenwolf unsere Heimat angreift. Aber so leicht wird das nicht, denn Draka wird ihn für jeden einzelnen unserer Gefallenen zehnfach zahlen lassen. Doch wir müssen schnell zurückkehren, um diese Bastarde zu verjagen.\n\nIhr habt Euch mit Euren Streitkräften als wertvolle Verbündete der Frostwölfe erwiesen. Eure Hilfe bei der Sicherung unseres Wor'gol wäre sehr willkommen.\n\nWir sehen uns auf dem Schlachtfeld, solltet Ihr Euch dazu entscheiden.", sourceObjective = "Rettet Wor'gol vor dem Donnerfürstenklan.", completion = "Durotans Vertrauen in Euch ist gut gesetzt, {name}. Meines habt Ihr ebenfalls gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33469] = { id = 33469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scharfseher", description = "Der Kriegsanführer der Donnerfürsten... {name}, Ihr müsst ihn aufhalten.\n\nEr ist aufgebrochen, um Drek'Thar am Teich der Visionen im Nordwesten anzugreifen!", sourceObjective = "Geht zum Teich der Visionen und tötet Kriegsanführer Gargrak.", completion = "Wolfsheim ist gerettet, aber ich spüre, dass ein stärkerer Feind kurz hinter dem Horizont lauert.", sourceObjectiveStatus = "unverified-source-field" }
quests[33470] = { id = 33470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Teich der Visionen", description = "Ein schrecklicher Sturm zieht am Horizont auf, {class}.\n\nIch habe ein Ritual vorbereitet. Ihr müsst den Teich konsultieren, um zu sehen, was das Schicksal für uns alle bereithält.", sourceObjective = "Sprecht mit Scharfseher Drek'Thar am Teich der Visionen, um das Ritual der Visionen zu beginnen.", completion = "Diese Eiserne Flut droht, ganz Draenor zu überschwemmen.\n\nDer Teich hat Euch eine mögliche Zukunft gezeigt. Wir dürfen nicht zulassen, dass sich diese Vision von der Vernichtung des Frostwolfklans erfüllt.\n\nIhr müsst sie aufhalten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33473] = { id = 33473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Speerspießerfestung", description = "Ihr müsst Durotan von Eurer Vision erzählen. Pul Windschneider kann Euch zurückfliegen.\n\nDas Schicksal des Frostwolfklans… und das von ganz Draenor liegt jetzt in Euren Händen, {name}.", sourceObjective = "Kehrt zu Durotan bei der Speerspießerfestung zurück.", completion = "Das sind wahrlich schlechte Neuigkeiten, {name}.\n\nZum Dank für die Rettung von Wolfsheim werde ich Euch ab sofort \"Wolfbruder\" nennen.\n\nAber jetzt müssen wir den Frostfeuergrat gegen den Donnerfürstenklan und die Eiserne Horde verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33483] = { id = 33483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mulvericks Misere", description = "Man hat Euch geschickt, um mich zu befreien? Dann sind wir wohl so etwas wie Verbündete.\n\nDer Sklavenmeister Turgall in der Rußgeschwärzten Mine sollte den Schlüssel zu diesem Käfig haben.\n\nUnd wenn Ihr schon da seid… Könnt Ihr mal nachschauen, welcher dieser feigen Vorarbeiter meine Äxte an sich genommen hat?", sourceObjective = "Besorgt den Schlüssel von Sklavenmeister Turgall und sucht nach Mulvericks Äxten.", progress = "Diese Oger werden meine Axt schon bald kennenlernen.", completion = "Mein aufrichtiger Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33484] = { id = 33484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Sklavenmeisters", description = "Erzählt den anderen von den Frostwölfen, die Ihr heute gerettet habt. Sie werden hocherfreut sein, zu erfahren, dass einige es lebend aus den Minen herausgeschafft haben.", sourceObjective = "Sprecht mit Guse in der Speerspießerfestung.", completion = "Habt Ihr Mulverick gefunden?\n\nNachdem Ihr ihren Meister besiegt habt, sollte es nicht lange dauern, bis die Oger hier verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33485] = { id = 33485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Multiplayer Race", description = "Rennt durch den Bogen...\nErreicht die blaue Markierung...\nErreicht die grüne Markierung...\nErreicht die rote Markierung...\nErreicht die violette Markierung,\ndann kehrt hierher zurück.\nUnd dann noch mal von vorn. Jawohl – 2 Runden!\n\nViel Glück!", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung, dann die rote Markierung, dann die violette Markierung und kehrt schließlich zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33492] = { id = 33492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northshire Sprint Practice", description = "Willkommen bei den Eisengnomspielen! Hier gilt: Rennt durch den Bogen...\nErreicht die blaue Markierung...\nErreicht die grüne Markierung...\nDann kehrt hierher zurück.\n\nhr könnt Euch dafür so viel Zeit nehmen, wie Ihr braucht.", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33493] = { id = 33493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Rudel", description = "Zum Teil stimme ich mit Karg überein: Wir KÖNNTEN den Eisenwolf jetzt herausfordern. Meine Faust ballt sich schon, wenn ich seinen Namen höre. Meine Muskeln schreien nach Rache.\n\nAber dann – in meinem Herzen – fühle ich Asha. Sie beruhigt mich und leitet mich. Ich verdiene ihre Weisheit nicht, aber sie ist ein Geschenk, das ich nicht verschwenden werde.\n\n<Lokra blinzelt in den Himmel.>\n\nDurotan und die andern werden sich ungefähr jetzt in Eurer Garnison sammeln. Wir sollten zu ihnen gehen.", sourceObjective = "Sprecht mit Durotan in Eurer Garnison.", completion = "Lokra hat schon immer die Geduld und die Selbstbeherrschung ihrer älteren Schwester gefehlt. Sie stürzt sich kopfüber in Probleme und verlässt sich darauf, dass ihre Fähigkeiten sie schon zum Sieg führen werden.\n\nBei der Art und Weise, wie sie und Karg einander ansehen, bin ich nicht überrascht, dass sie ihm den ganzen Weg bis Grom'gar hinterhergejagt ist. Was mich überrascht, ist, dass sie es zurückgeschafft haben.\n\nIch schätze, das haben wir wie so oft Euch zu verdanken. Wieder ehrt Ihr uns mit Euren Taten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33497] = { id = 33497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zeitverzerrter fallender Schläger 2" }
