quests[33512] = { id = 33512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mit Lava sattgefressener Goren" }
quests[33513] = { id = 33513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzdorns Leutnants", description = "Amnennars Wiedergeburt steht unmittelbar bevor. Um die Zeremonie zu schützen, hat Todessprecher Schwarzdorn seine vertrauenswürdigsten Leutnants zwischen uns und ihm aufgestellt.\n\nAarux, eine verseuchte Spinne, nistet in der Nähe ihrer Jungen. Aranomanten der Totenköpfe kümmern sich um sie. Mordresh ruft Amnennars Kräfte auf dem Knochenhaufen zusammen. Und dann steht da noch Schwämmerl und bewacht den Zugang zum Wendel der Dornen.\n\nSobald Ihr diese Wächter besiegt habt, werde ich zu Euch stoßen und wir werden gemeinsam Schwarzdorn die Stirn bieten.", sourceObjective = "Tötet Aarux, Mordresh und Schwämmerl.", completion = "Ihr habt Euch gut geschlagen, aber das ist nur die eine Hälfte des Kampfs. Jetzt, da das Gerüst seiner Verteidigung wankt, ist es Zeit, den Schlag gegen Todessprecher Schwarzdorn zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33514] = { id = 33514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ritual", description = "Es ist gut, dass Ihr so schnell gekommen seid. Ich muss Euch bitten, Euer Leben noch einmal in Gefahr zu bringen, um Kalimdor zu retten.\n\nAmnennars Lehrling, Todessprecher Schwarzdorn, hofft, seinen Meister in das Land der Lebenden zurückzuholen! Wir müssen uns schnell oben auf den Wendel der Dornen begeben und ihn besiegen, bevor das Ritual vervollständigt wird. Wir müssen gemeinsam zuschlagen, nur mit vereinten Kräften haben wir eine Chance, ihn aufzuhalten!", sourceObjective = "Tötet Amnennar den Kältebringer.", progress = "Schnell, {name}, Ihr müsst dem Ritual ein Ende setzen! Amnennar darf nicht zurückkehren.", completion = "Sehr gut gemacht, {name}. Da Amnennars Phylakterium jetzt vom Roten Drachenschwarm geschützt wird, können wir wieder ruhig schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33525] = { id = 33525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Orcpärchen" }
quests[33526] = { id = 33526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgeben ist keine Option", description = "Die Speerspießer plagen mein Volk schon seit vielen Jahren.\n\nDem setzen wir heute ein Ende!\n\nJetzt müssen wir es den Ogern nur noch so erklären, dass sie es auch verstehen.\n\nWenn Ihr uns immer noch helfen wollt, dann steckt unser Banner in die Leichen unserer Feinde.\n\nWenn sie das Schlachtfeld voller Frostwolftrophäen sehen, wird sie der Mut verlassen!\n\nDas ist bei uns so Sitte. Ich treffe Euch dann weiter vorn, wenn Ihr die Aufgabe erledigt habt.", sourceObjective = "Verwendet 8 Frostwolfbanner bei toten Ogern der Speerspießer.", completion = "Das sind keine gewöhnlichen Feinde. Und doch habt Ihr keinerlei Schwäche gezeigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[33527] = { id = 33527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Schritte", description = "In seinem Zorn hat sich Ga'nar aufgemacht, Gorr'thog, den Ogerkönig, zu bekämpfen.\n\nEr ist allein, aber die Rampe zum Thronsaal ist jetzt blockiert.\n\nIhr habt Euch schon mehrfach als nützlich erwiesen. Vielleicht findet Ihr ja einen anderen Weg dort hinauf?\n\nIch bin auf dem Weg hierher verletzt worden, aber ich werde mir einen Weg zur Rampe bahnen, damit wir dort wieder zueinander finden können.\n\nBeeilt Euch, <Reisender/Reisende>. Ihr müsst dafür sorgen, dass dem Frostwolfklan der Angriff auf diese Festung gelingt.", sourceObjective = "Klettert die Kette hinauf und tötet Gorr'thog.", completion = "Wir nannten Euch Außenseiter, {race}, aber Ihr habt die Stärke und das Herz eines Frostwolfs gezeigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[33530] = { id = 33530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraum im Grab", description = "Da unten... furchtbar... überall Leichen...\n\nDunkles Ritual... bitte... Ihr müsst sie aufhalten...", sourceObjective = "Geht dem Ritual im Grab der Seelen auf den Grund.", completion = "Es wäre eine Katastrophe, wenn dieser Teron'gor die Kontrolle über Auchindoun erlangt!\n\nWir müssen ihn aufhalten, bevor seine Macht wächst!", sourceObjectiveStatus = "unverified-source-field" }
quests[33531] = { id = 33531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Gefallener Oger" }
quests[33532] = { id = 33532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Ogerschatz" }
quests[33533] = { id = 33533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse von Gorgrond", description = "Unser heutiger Sieg ist uns teuer zu stehen gekommen. Zu teuer. Ich bin nicht sicher, dass wir einen weiteren Angriff abwehren können.\n\nWir müssen wissen, was die Eiserne Horde vorhat, und es gibt nur einen Ort, an dem wir das herausfinden können.\n\nGorgrond.\n\nEin wildes Land, aus dem nur wenige je zurückkehren.\n\nIch werde dorthin gehen, ich werde ihre Festung beim Schwarzfels finden und ich werde herausfinden, wie die wilden Orcs zu besiegen sind.\n\nWollt Ihr mich begleiten, Kommandant?", sourceObjective = "Sucht Yrel am Wildwuchsbett in Gorgrond auf. Sprecht mit dem Greifenmeister Eurer Garnison, um dorthin zu fliegen.", completion = "Willkommen in Gorgrond, Kommandant. Wir sind selbst gerade erst angekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33540] = { id = 33540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Uzkos Krimskrams" }
quests[33543] = { id = 33543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lachenden Schädel", sourceObjective = "Findet ein Stammesmitglied des Lachenden Schädels.", completion = "Ha! Interessant. Was seid Ihr denn?", sourceObjectiveStatus = "unverified-source-field" }
quests[33544] = { id = 33544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goren gründlich getilgt!", description = "Wir... Wir haben uns viel zu lange nicht mehr um die Goren gekümmert. Sie sind viel zu frech geworden und haben bereits vergessen, wer wir sind.\n\nTötet sie! Tötet sie alle. Zerstückelt sie, bis sie vor Schmerzen schreien. Erinnert sie daran, was es bedeutet, ein Dorf des Lachenden Schädels anzugreifen.\n\nOh, und übrigens: Willkommen in Gorgrond.", sourceObjective = "Tötet 8 Säurezahnverschlinger.", sourceObjectiveStatus = "unverified-source-field" }
quests[33546] = { id = 33546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvollendete Taten", description = "In seiner Eile ist Ga'nar vorgerückt, bevor dieses Gebiet gesichert wurde. Er ist wohlgemerkt ein unvergleichlicher Krieger, doch seine Taktiken sind mitunter kostspielig.\n\nGol'kosh und seine Truppen erhielten den Befehl, die gegnerischen Vorräte zu vernichten, aber die Oger haben das Öl gestohlen, das er dazu gebraucht hätte.\n\nHolt das Öl zurück und sorgt dafür, dass die Truppen ihre Mission ausführen. Wenn sie dann noch leben, sagt ihnen, sie sollen sich mit mir am Eingang zur Zitadelle treffen.\n\nIch muss mich darum kümmern, dass meine verwundeten Brüder in Sicherheit gebracht werden.", sourceObjective = "Sammelt Fässer mit Frostwolföl und bringt sie zu Gol'kosh in den Vorratsraum.", progress = "Lok'tar.", completion = "Gol'kosh hat seine Mission also abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33548] = { id = 33548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sterben lachend!", description = "Seid Ihr hier, um zu helfen oder um im Weg zu stehen?\n\nDieses Dorf wird gerade verschlungen und wir müssen schleunigst retten, was wir können.\n\nBergt die Masken unserer gefallenen Brüder und Schwestern vom Lachenden Schädel und trefft mich dann auf der Westseite des Dorfes.\n\nIch werde diese Masken benötigen, um unseren Klan wieder aufzubauen.", sourceObjective = "Sammelt 5 Masken des Lachenden Schädels.", progress = "Wir sind der Lachende Schädel! Wir erzittern nicht im Angesicht des Todes. Wir lachen ihm ins Gesicht!", completion = "Sie sind mehr als nur lustige Gesichtsbedeckungen. Mit einer Maske und dem richtigen Ansporn können wir jeden zu einem Lachenden Schädel machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33550] = { id = 33550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Nickermeister der Eisernen Horde" }
quests[33561] = { id = 33561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Multiplayer Race", description = "Rennt durch den Bogen...\nErreicht die blaue Markierung...\nErreicht die grüne Markierung...\nErreicht die rote Markierung...\nErreicht die violette Markierung,\ndann kehrt hierher zurück.\nUnd dann noch mal von vorn. Jawohl – 2 Runden!\n\nViel Glück!", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung, dann die rote Markierung, dann die violette Markierung und kehrt schließlich zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33562] = { id = 33562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophäe: Gorg'aks Obsidianstacheln" }
quests[33563] = { id = 33563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augenschmaus", description = "Ihr da! Kämpft mit oder geht aus dem Weg.\n\nDas ist kein normaler Gorenangriff. Seht mal da drüben: Ein Gronnling macht sich über unsere Vorräte her. Dieser buckelige Gorenabschaum hat ein Stück aus meiner geliebten Medulla herausgebissen!\n\nReißt ihm das Auge aus der Stirn und bringt es mir.\n\nDas sollte mir genug Zeit verschaffen, Medulla aus diesem Gorenloch herauszubringen.", sourceObjective = "Besorgt Skothwas Auge.", progress = "Hat das Ding vor Schmerzen geschrien? Um Gnade gewinselt? Habt Ihr es erst getötet und ihm dann das Auge genommen? Erzählt mir alles.", completion = "Diese Marionetten der Magnaron werden für die Schädel, die sie uns heute genommen haben, bezahlen.\n\nDieses Auge werde ich vorläufig am Gürtel tragen, damit der Narr, den Ihr getötet habt, dabei zuschauen kann, wie ich seine Brüder bis zu meinem letzten Atemzug abschlachten werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[33564] = { id = 33564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Hängender Ranzen" }
quests[33565] = { id = 33565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schimärenschuppe" }
quests[33566] = { id = 33566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Vollgelaufene Truhe" }
