quests[33575] = { id = 33575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Dämonentruhe" }
quests[33578] = { id = 33578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrophobie", description = "W-wir haben den Arakkoa n-n-nichts getan... W-warum greifen sie Aruuna an? Was wollen sie von uns?\n\nIch würde am liebsten weglaufen, aber... ich habe zu viel Angst. Ihr Anführer würde mich rösten, da bin ich mir ganz sicher!\n\nE-er ist im Gasthaus...", sourceObjective = "Schaltet den Sonnenweisen Kairyx aus.", completion = "Ihr habt ihn töten können? Oh, Oh, ich danke Euch!\n\nAber was hat er da über ein Artefakt gesagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[33579] = { id = 33579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fund der Draenei", description = "Sie waren hinter einem Artefakt her? Dann müssen die Minenarbeiter in unserer Kristallmine im Norden irgendetwas Besonderes gefunden haben.\n\nBeim Licht, könnt Ihr Euch vorstellen, wie mächtig das Ding sein muss, wenn sie deswegen den langen Weg von ihren Festungen bis hierher auf sich genommen haben?\n\nIch gehe davon aus, dass sie es an sich genommen haben... Es wäre geradezu verrückt, jetzt danach zu suchen...", sourceObjective = "Untersucht das uralte Prisma in der Kristallmine von Aruuna.", completion = "Ich war schon besorgt, dass Ihr auf meine kleine Maskerade nicht hereinfallen würdet. Aber Ihr habt Eure Rolle perfekt gespielt.\n\nIch möchte Euch sogar um einen weiteren Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33580] = { id = 33580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Säuberungsaktion im Shadarversteck", description = "Es herrscht keine Gleichheit unter den Arakkoa.\n\n<Iskar zieht seinen Ärmel hoch und zeigt eine verkrüppelte und funktionslose Schwinge.>\n\nDas ist keine Illusion. Das haben sie mir angetan. Noch bevor sie mir einen Namen gaben, haben sie mir einen Platz in der Gesellschaft zugewiesen: ganz unten.\n\nEs gibt viele von uns. Wir leben an den vergessenen Orten dieser Welt.\n\nDas Shadarversteck war ein solcher Ort, aber die Jünger haben ihn aufgespürt und eine Säuberungsaktion gestartet. Im Namen der Moral. Zu ihrem Vergnügen.\n\nWenn Ihr meinen Leuten zur Flucht verhelft, stehen wir in Eurer Schuld.\n\nWenn der Himmel brennt, zahlt es sich aus, Verbündete in den Schatten zu haben.", sourceObjective = "Helft 8 ausgestoßenen Arakkoa, aus dem Shadarversteck zu entkommen.", completion = "Ihr werdet sehen, {race}: Aruuna und das Shadarversteck waren nur der Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[33581] = { id = 33581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotenes Wissen", description = "<Die Augen des Dunkelsehers Raastok formen sich zu Schlitzen, während er Euch mustert.>\n\nIhr seid also Iskars bezahlte Hilfe? Mir persönlich ist es egal, ob Ihr nun <ein/eine:r> {race} seid oder eine zu groß geratene Motte. Wir können auf jeden Fall Hilfe gebrauchen.\n\nDie Jünger von Rukhmar sind blinde Narren! Sie haben alle Studien der Schattenmagie verboten und bezichtigen alle der Ketzerei, die in der Dunkelheit nach anderen Antworten suchen.\n\nWir haben viele Folianten mit verbotenem Wissen im Shadarversteck verwahrt. Ich werde Euch entlohnen, wenn Ihr so viele davon wie möglich vor den Flammen bewahrt.", sourceObjective = "Findet 6 Schattenfolianten im Shadarversteck.", progress = "Wie krank muss man sein, um ein Buch voller völlig brauchbarer dunkler Künste zu verbrennen?", completion = "Ja, ja. Ausgezeichnete Arbeit. Da sind ein paar meiner Lieblingstitel dabei.\n\nWissen ist Macht. Und jetzt kann ich mich gut gerüstet auf den Weg zu den Spitzen machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33582] = { id = 33582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuras Rache", description = "Ich war selbst eine Flügelwache, vor langer Zeit.\n\nEines Nachmittags hat man mich erwischt, als ich meinen Posten verlassen hatte. Ich wollte mir nur für eine Stunde die Feierlichkeiten anschauen... Kuuan sollte mich decken. Aber stattdessen hat er mich bei den Vorgesetzten verraten, um sich bei ihnen beliebt zu machen.\n\nSie haben mir die Augen ausgerissen, mir die Flügel gebrochen und mich von den Spitzen gestürzt.\n\nUnd doch kann ich von Glück sprechen. Denn wenn Iskar mich nicht gefunden hätte, wäre ich gestorben. Und jetzt taucht Kuuan an genau dem Tag im Shadarversteck auf, an dem Ihr Eure Söldnerdienste anbietet. Das nenne ich wahres Glück.", sourceObjective = "Tötet Flügelwache Kuuan im Shadarversteck.", completion = "Und was das Glück betrifft, könnt Ihr Euch glücklich schätzen, dass ich nicht mehr zu den Verteidigern von Aruuna zähle. Denn ich hätte Euch ausgeweidet, bevor ihr dem Feuerweisen auch nur nahe gekommen wäret.\n\nAch, manchmal vermisse ich die alten Zeiten.\n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[33584] = { id = 33584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: A'kumbos Asche" }
quests[33586] = { id = 33586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenspiele", description = "Nicht alle Schattenmondorcs haben sich Ner'zhuls Bündnis mit der Eisernen Horde angeschlossen.\n\nUnter ihnen ist eine Orcfrau, mit der ich mich vor vielen Jahren angefreundet habe. Sie könnte uns vielleicht mehr über Ner'zhuls Pläne bezüglich dieses \"dunklen Sterns\" sagen.\n\nSie befindet sich auf der Anhöhe der Exilanten im Nordosten. Ich werde eine Nachricht vorausschicken, damit sie Eure Ankunft erwartet.", sourceObjective = "Sprecht mit Rulkan bei der Anhöhe der Exilanten.", completion = "Ich habe geahnt, dass dieser Tag kommen würde. Der Prophet der Draenei tut gut daran, meinen Rat zu suchen, Reisender.\n\nObwohl wir nicht oft miteinander sprechen, respektieren wir uns gegenseitig sehr.\n\nIch kenne die Leiden seines Volks und ich glaube nicht, dass der Schattenmondklan noch auf den Pfaden unserer Ahnen wandelt.\n\nDeshalb werde ich Euch helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33593] = { id = 33593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dramatisches Signal", sourceObjective = "Feuert Pennys Leuchtpistole ab, während Ihr in Todesgrimasse seid.", progress = "He, Kommandant!", completion = "Das scheint nicht viel gebracht zu haben, außer unsere Position an alle Kreaturen in ganz Gorgrond zu verraten.\n\nWartet, habt Ihr das auch gehört?", sourceObjectiveStatus = "unverified-source-field" }
