quests[33609] = { id = 33609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northshire Dash Practice", description = "Willkommen bei den Eisengnomspielen! Hier gilt: Rennt durch den Bogen, erreicht die blaue Markierung und kehrt dann so schnell wie möglich hierher zurück.\n\nIhr könnt Euch so viel Zeit nehmen, wie ihr braucht.", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33610] = { id = 33610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Begräbnisfelder B" }
