quests[33614] = { id = 33614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Grekas Urne" }
quests[33622] = { id = 33622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Schlachtbank", description = "Dank Eurer Hilfe ist der Eingang der Festung jetzt wieder gesichert.\n\nDrinnen sieht es allerdings etwas anders aus. Findet einen Weg hinein und schaltet alle Oger auf Eurem Weg aus.", sourceObjective = "Tötet 10 Oger in der Speerspießerfestung.", progress = "Ja?", completion = "Und wieder treffen wir uns...", sourceObjectiveStatus = "unverified-source-field" }
quests[33633] = { id = 33633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wühler der Gefräßige", description = "Der streunende Eber durchwühlt den Müll, der von der Eisernen Horde zurückgelassen wurde. Er hört auf zu kauen, starrt Euch an und rülpst.\n\nEr stinkt furchtbar.\n\nScheinbar kaut er auf einem Stück verfaultem Fleisch herum. Vielleicht könnt Ihr etwas Gesünderes für seine Zwischenmahlzeit finden?", sourceObjective = "Findet Futter für Wühler am Wühlerpass in Gorgrond.", progress = "Das vergammelte Fleisch sieht widerlich aus. Findet Wühler etwas Gesundes zum Essen.", completion = "Ihr füttert den hungrigen Eber mit den Kaktusfeigen. Er verschlingt sie am Stück und schmatzt mit den Lippen.\n\nWühler springt Euch an und leckt Euch mit seiner ekligen Zunge durchs Gesicht.\n\nAnscheinend habt Ihr einen neuen Freund gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33635] = { id = 33635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Seen Gazebo Explosion" }
