quests[33649] = { id = 33649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Verbrannter Eiserner Späher" }
quests[33657] = { id = 33657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einrücken", description = "Gorr'thog ist jetzt tot. Es ist an der Zeit, unsere Stellung in der Speerspießerfestung zu sichern. Trefft mich unten, damit wir damit beginnen können, hier Stärke zu zeigen.", sourceObjective = "Trefft Euch mit Durotan bei der Speerspießerfestung.", completion = "Ihr habt Großes erreicht. Ohne Euch hätten wir diese Zitadelle nicht einnehmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[33660] = { id = 33660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plünderung der Saberon", description = "Diese Vorräte bestehen zum größten Teil aus alten Tierteilen und anderem Krempel. Auf den zweiten Blick ist darunter aber auch ein Bündel Kräuter und Pflanzen.\n\nVielleicht erweist sich ja Rakthoth als etwas hilfsbereiter, wenn man ihr ein paar dieser Kräuterbündel bringt...", sourceObjective = "Findet 8 Kräuterbündel unter den Saberonvorräten auf der Dampfnarbenanhöhe.", progress = "Ich benötige noch mehr Reagenzien, bevor ich zu meinen Brüdern und Schwestern zurückkehren kann.", completion = "Dann verwahren sie ihre Sachen jetzt also nicht mehr in den Vorratshöhlen, sondern in ihren persönlichen Vorräten. Gut zu wissen.\n\nIhr habt mir einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33661] = { id = 33661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dampfnarben\"zutaten\"", description = "Kommen wir also jetzt zu einer Herzensangelegenheit, he he. Die Saberon haben starke Herzen und unsere Schamanen haben viele Verwendungsmöglichkeiten für sie.\n\nIch werde die Magie des Urtums erforschen, wenn Ihr mir welche bringt. Abgemacht?", sourceObjective = "Sammelt 10 Saberonherzen von lebenden Saberon auf der Dampfnarbenanhöhe.", progress = "Ich brauche diese Herzen, {class}.", completion = "Das sind gute, starke Herzen! Hervorragende Arbeit, {class}. Ich werde mich an meinen Teil der Abmachung halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33662] = { id = 33662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufmaul gegen Felsen", description = "Nachdem die Saberon diese Pflanzen bestohlen hatten, wurden sie in höhere Bereiche der Dampfnarbenanhöhe zurückgedrängt und haben sich dort verbarrikadiert. Ich selbst habe keinen Weg hinein gefunden, aber Ihr könntet es schaffen.\n\nEiner der Pfade ist durch einen Felsen blockiert, aber er scheint brüchig zu sein. Ein starker Krieger könnte ihn sicher brechen – ein Oger zum Beispiel.\n\nUnd soweit ich weiß, kennt Ihr einen Ogergladiator...", sourceObjective = "Durchbrecht mithilfe des Gladiators Aufmaul die Felsbarriere.", completion = "Gute Arbeit. Aber wir müssen uns beeilen, bevor die Pflanzen bemerken, dass der Weg frei ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[33663] = { id = 33663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredder gegen Saberon", description = "Nachdem die Saberon diese Pflanzen bestohlen hatten, wurden sie in höhere Bereiche der Dampfnarbenanhöhe zurückgedrängt und haben sich dort verbarrikadiert. Ich selbst habe keinen Weg hinein gefunden, aber Ihr könntet es schaffen.\n\nEiner der Pfade ist durch ein Bündel harter Ranken blockiert. Ich hörte, dass Ihr über eine Maschine verfügt, die diese Ranken mit Leichtigkeit zerschreddern kann.\n\nVielleicht könnt Ihr Euch ja auf diese Maschine setzen und diese Ranken beseitigen.", sourceObjective = "Räumt mit Hilfe des Schredders die Rankenbarriere aus dem Weg.", completion = "Gute Arbeit. Aber wir müssen uns beeilen, bevor die Pflanzen bemerken, dass der Weg frei ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[33664] = { id = 33664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gorum" }
quests[33684] = { id = 33684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tintenmeister des Arboretums", description = "Ich habe gehört, dass die Tintenmeister im Arboretum die Hilfe eines Schreibers mit den besten Fähigkeiten benötigen. Unterhaltet Euch mit Tintenmeister Wei, wenn Ihr helfen wollt.", sourceObjective = "Sprecht mit Tintenmeister Wei im Arboretum im Jadewald.", sourceObjectiveStatus = "unverified-source-field" }
quests[33685] = { id = 33685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschafter der Urtume", description = "Ich habe einen finster aussehenden \"Baum\" in diesem Wäldchen gesehen. Er weint und seufzt, aber er verhält sich nicht feindselig.\n\nVielleicht weiß er ja, wie man diese Pflanzen los wird. Geht und findet es heraus.", sourceObjective = "Sprecht mit Borkus bei Dionors Ende in Gorgrond.", completion = "Also deswegen haben sich die Saberon dort oben verbarrikadiert. Sie sind gute {class}, {name}. Ich muss da rein!\n\nIch habe so eine Vorstellung, was mich da erwartet...", sourceObjectiveStatus = "unverified-source-field" }
quests[33689] = { id = 33689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzen stutzen", description = "Ich habe nicht weit von hier eine Jagdhöhle, wo ich meine Trophäen und Reagenzien für den Lachenden Schädel aufbewahre. Vor Kurzem griff ein riesiges Pflanzenmonster aus dem Wildwuchs an und wurde von ein paar der riesigen Felsmonster getötet. Nach seinem Tod sind viele kleinere Pflanzenbestien aufgetaucht und haben alles verwüstet.\n\nUnd sie haben mich von meiner besten Reagenzienquelle abgeschnitten. Tötet sie, dann werde ich versuchen, meine Höhle zu erreichen und zu retten, was ich kann...", sourceObjective = "Tötet 12 Verteidiger bei Dionors Ende.", completion = "Sie kommen immer wieder! Ich will dieses Jagdgebiet nicht aufgeben müssen. Ich schwöre, dass wir einen Weg finden werden, diesen Wildwuchs zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33694] = { id = 33694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien von Rakthoth", description = "Die Zerstörung unseres Dorfes wird uns noch eine ganze Weile beschäftigen. Unsere beste Jägerin, Rakthoth, \"findet\" Reagenzien für unsere Schamanen.\n\nWir haben sie schon eine ganze Weile nicht mehr gesehen und wir brauchen diese Substanzen dringender denn je. Begebt Euch in ihr Jagdgebiet und findet heraus, ob sie noch am Leben ist.", sourceObjective = "Sucht Rakthoth bei Dionors Ende in Gorgrond.", completion = "Medulla hat Euch geschickt? Unser Dorf ist zerstört? Ich wäre ja schon lange zurückgekehrt, wenn diese verdammten Pflanzenbestien nicht wären!", sourceObjectiveStatus = "unverified-source-field" }
quests[33695] = { id = 33695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf die Todesblüte", sourceObjective = "Nehmt Rauchmeister Fletsch auf der Dampfnarbenanhöhe die Todesblüte ab.", progress = "Habt Ihr etwas für mich, kleines Wesen?", completion = "Ihr... Ihr habt mir die Blüte gebracht. Endlich kann sich meine Bestimmung erfüllen!", sourceObjectiveStatus = "unverified-source-field" }
quests[33706] = { id = 33706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Ruhe für Dionor", description = "Mit dieser Blüte habt Ihr mir einen enorm wertvollen Dienst erwiesen. Jetzt kann ich endlich Dionor ein für alle Mal in den Wildwuchs zurückschicken und diesen Alptraum beenden. Es muss nur noch das Ritual abgehalten werden... bleibt und werdet <Zeuge/Zeugin> von etwas, das Ihr nie wieder erleben werdet...", sourceObjective = "Schaut Borkus' Ritual zu.", completion = "Endlich ist es vollbracht. Dionor ist fort und seine Brut sollte ihm bald folgen.\n\nIch bin dieses Kampfes müde und habe keine Verlangen mehr, zur Überwucherung zurückzukehren.\n\nVielleicht werde ich dieses Land verlassen und mich auf Reisen begeben, um zu sehen, welche Überraschungen ihr kleinen Wesen noch zu bieten habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[33707] = { id = 33707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons Among Us - Horde" }
quests[33720] = { id = 33720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrangieren!", description = "Ketya Eisenschredder,\n\nEure neuen Eisenschredder bedrohen unsere eigenen Soldaten.\n\nNehmt den Prototyp außer Betrieb und verwahrt ihn in der Höhle am Taladorstrand, bis Ihr den Konstruktionsfehler gefunden habt.\n\nIn der Zwischenzeit werde ich Ingenieur Draxen damit beauftragen, die Maschine weiterzuentwickeln.\n\n- Orgrim Schicksalshammer", sourceObjective = "Findet den ausrangierten Eisenschredder in der nahe gelegenen Höhle und entwendet ihn von Ingenieur Draxen.", completion = "Ein Eisenschredder-Prototyp, was? Ich wette, dass wir dieses Ding zum Laufen bekommen... sie hatten ja niemanden wie MICH, um ihn zu reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[33721] = { id = 33721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazlowes Lösung", description = "Ich habe einige wichtige Ziele im Wald da unten ausgemacht.\n\nWenn Ihr Euch einem nähert, könnt Ihr meine Lösung anwenden.\n\nWendet sie an und die Ziele werden mit großem Trara neutralisiert werden.", sourceObjective = "Zerstört die Vorräte der Donnerfürsten, die Schwarzfelsschmiede und das Holzlager.", completion = "Ich liebe gute Explosionen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33722] = { id = 33722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu viele Eisen im Feuer", description = "Wir dürfen uns nicht voreilig in die Schlacht stürzen. Bevor wir uns aufmachen, Orgrim zu fassen, müssen wir uns zunächst seinen Truppen widmen.\n\nWenn wir Erfolg damit haben wollen, die Eiserne Horde aus Talador zu vertreiben, dann müssen wir an diesen Gestaden damit beginnen.", sourceObjective = "Tötet 15 Mitglieder der Eisernen Horde an der Orunaiküste.", completion = "Das wären ein paar Feinde weniger, die uns in den Rücken fallen können. Lok'tar.", sourceObjectiveStatus = "unverified-source-field" }
quests[33724] = { id = 33724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Band mit X Seiten", description = "Die Bedienungsanleitung für den Schredder war hier dazwischengeklemmt, aber es fehlen viele Seiten. Wir müssen so viele davon wie möglich finden, dann könnte – KÖNNTE – ich den Schredder vielleicht wieder zum Laufen bringen.\n\nDer Windrichtung nach zu urteilen könnte ich wetten, dass die Seiten in Richtung des Belagerungspostens Archenon geflogen sind.", sourceObjective = "Findet 20 Seiten der Bedienungsanleitung beim Belagerungsposten Archenon.", progress = "Ich weiß nicht, warum diese Idioten nicht einfach alle Seiten an einem Ort aufbewahren.", completion = "Sehr detailliert... fast so, als ob ein Goblin es geschrieben hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[33727] = { id = 33727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heal Up" }
quests[33728] = { id = 33728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge um Spionenauge", description = "Ganz ausgezeichnet! Ich mache mich aus diesen Seiten mal schlau und bringe den Eisenschredder fix wieder in Gang!\n\nBlickt in der Zwischenzeit schon mal durch mein Aug' und Ohr. An den Ort seid Ihr schon bald unterwegs!", sourceObjective = "Werft einen Blick durch Gazlowes Aug' und Ohr.", completion = "Orgrim scheint nichts Gutes im Schilde zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33729] = { id = 33729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Schreddern geboren", description = "Der Eisenschredder ist startklar! Er ist in Topform und wartet nur darauf, unsere Feinde in Tuurem zu schreddern!\n\nZieht los und richtet so viel Schaden wie möglich an. Ich muss sagen, ich bin echt neidisch.", sourceObjective = "Tötet in Tuurem 100 Mitglieder der Eisernen Horde mit dem Eisenschredder.", completion = "– FEINDE ELIMINIERT –", sourceObjectiveStatus = "unverified-source-field" }
quests[33730] = { id = 33730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruierter Untergang", description = "– MUTTER ENTDECKT. WARNUNG! WARNUNG! –", sourceObjective = "Besiegt Ketya Eisenschredder in Tuurem.", completion = "Gazlowes Hilfe bei der Sicherung Taladors war von unschätzbarem Wert. Jetzt ist es an uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[33731] = { id = 33731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Shattrath", description = "Um die Eiserne Horde aufzuhalten, müssen wir Vorurteile überwinden und zusammenarbeiten... und sei es nur zu diesem Zweck.\n\nHorde, Allianz, Vergangenheit, Gegenwart... All das ist bedeutungslos angesichts dieses Feinds.\n\nGemeinsam werden wir Shattrath zurückerobern... oder bei dem Versuch sterben.", sourceObjective = "Vertreibt die Eiserne Horde aus Shattrath.", completion = "Ich kann nicht glauben, dass Orgrim wirklich tot ist. Schwarzfaust hat mir einen Teil meines Herzens herausgerissen. Und ich werde ihn vernichten, sobald sich mir die Gelegenheit dazu bietet.", sourceObjectiveStatus = "unverified-source-field" }
quests[33732] = { id = 33732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage Siege Weapons" }
quests[33734] = { id = 33734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile von uns", description = "Als die Feuer ausbrachen, nahm ich nur meine Tochter an die Hand, um zu fliehen. Das war natürlich die richtige Entscheidung. Aber ich vermisse ein paar Dinge, die wir zurücklassen mussten.\n\nIch bin schließlich ein Konstrukteur, ein Kristall- und Edelsteinformer. Aber ohne meine Werkzeuge bin ich einfach nur ein Flüchtling.\n\nDie städtischen Aufzeichnungen werden in einem Speicherkristall in der Ratshalle verwahrt. Damit kann ich das Wissen und das Erbe von Aruuna weitergeben.\n\nUnd... Meine Tochter ist sehr verängstigt. Es wäre großartig, wenn sie ihre Lieblingspuppe zurückbekommen könnte.", sourceObjective = "Bringt die Werkzeuge des Kristallformers, Melanis Puppe und die Annalen von Aruuna zurück.", progress = "Das sind nicht nur einfach irgendwelche Gegenstände. Sie repräsentieren unsere Lebensgrundlage, unsere Vergangenheit und Zukunft und unsere Hoffnung.\n\nSie sind Teile von uns.", completion = "Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[33735] = { id = 33735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangelware", description = "Der Feind hat Sprengladungen am Strand da unten deponiert. Wir müssen sie bergen, damit sie nicht gegen uns verwendet werden.\n\nBerichten zufolge sind Kisten mit Sprengstoff an der Küste entlang verstreut.\n\nWährend Ihr danach sucht, werden Durotan und ich weiter in das Gebiet der Eisernen Horde vordringen.", sourceObjective = "Sammelt 6 Sprengladungen der Eisernen Horde ein.", progress = "Habt Ihr die Sprengladungen der Eisernen Horde schon gefunden?", completion = "Ich glaube, wir können sie am Belagerungsposten Archenon verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33736] = { id = 33736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Eiserner Hand", description = "Die Orcs sind nicht die einzige Bedrohung. Wir haben sie zwar deutlich geschwächt, doch sie verfügen noch immer über recht starke Belagerungswaffen.\n\nSabotiert ihre Belagerungswaffen mit den Sprengladungen, die Ihr am Strand eingesammelt habt.", sourceObjective = "Zerstört 6 Belagerungsmaschinen der Eisernen Horde.", completion = "Es ist beruhigend, zu wissen, dass sie ihre Kriegsmaschinen nicht mehr gegen uns verwenden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[33740] = { id = 33740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennender Himmel", description = "Alles ging so schnell. Ein unglaublich heller Blitz hat die Wälder in der Nähe in Brand gesteckt und kurz darauf trieben furchtbare Winde die Flammen über ganz Aruuna.\n\nNur Augenblicke später griffen die Arakkoa aus dem Rauch heraus an.\n\nIch muss Melani zum Pilgerweg bringen. Von dort können wir zur Anachoretenrast und in den Schutz der Verteidiger gelangen. Da die Arakkoa überall ungehindert umherstreifen, fürchte ich, dass wir entdeckt oder von den Flammen eingeschlossen werden könnten.", sourceObjective = "Tötet 12 Invasoren der Jünger in Aruuna und der Kristallmine von Aruuna.", completion = "Ihr Tod bringt uns Aruuna nicht zurück. Aber zumindest ist es gut zu wissen, dass jemand unter uns ihnen etwas entgegenzusetzen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[33748] = { id = 33748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest -  Saberon Servent Snip Scene" }
quests[33749] = { id = 33749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questbelohnung Zusammenfassung: Zugdepot" }
quests[33750] = { id = 33750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questbelohnung Zusammenfassung: Pumpstation" }
quests[33754] = { id = 33754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in die Ferne", description = "Eure Verbündeten haben den Goblin Gazlowe mitgeschickt, damit er uns Ratschläge gegen die Eiserne Horde gibt. Bisher hat er sich als äußerst wertvoll erwiesen.\n\nEr hat ein Fernrohr aufgebaut, mit dem man in weite Fernen schauen und – so behauptet er – auch lauschen kann.\n\nBenutzt dieses Fernrohr und meldet mir, was Ihr gesehen habt. Ich bleibe bei meinem normalen Handfernrohr.", sourceObjective = "Werft einen Blick durch Gazlowes Aug' und Ohr.", completion = "Orgrim führt diese Orcs an? Warum hat er sich der Eisernen Horde verschrieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[33755] = { id = 33755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Test Race: 2 Laps", description = "Rennt durch den Bogen...\nErreicht die blaue Markierung...\nErreicht die grüne Markierung...\nErreicht die rote Markierung...\nUnd dann nochmal von vorn. Genau – 2 Runden!\n\nViel Glück!", sourceObjective = "Rennt durch den Bogen, erreicht die blaue Markierung, dann die grüne Markierung, dann die rote Markierung, dann die violette Markierung und kehrt schließlich zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33756] = { id = 33756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und nochmal, weil's so schön war!", description = "Ihr wollt noch mehr? So viel Einsatz lob' ich mir!\n\nVielleicht könnt Ihr diesmal Eure alte Bestzeit verbessern! Lauft von der Startposition zur blauen Markierung und von dort aus zur grünen, zur roten und schließlich zurück zur Startposition. \n\nEure Zeit ist wichtig, also beeilt Euch!", sourceObjective = "Rennt durch die Startposition, berührt die blaue, die grüne und zum Schluss die rote Markierung und kehrt dann zur Startposition zurück.", progress = "Ihr habt nicht alle Markierungen erreicht. Beeilt Euch!", completion = "Gut gemacht und gute Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[33761] = { id = 33761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barums Notizen", description = "<Dieser massive Foliant enthält Notizen über die Weiterverarbeitung und die Formgebung von Draenors Naturedelsteinen und -kristallen. Darunter sind auch mehrere ganzseitige technische Zeichnungen mit aufwändigen Vorlagen.\n\nDie letzten Einträge erläutern eine Reihe von Schliffen, die die Draeneiverteidiger im Kampf unterstützen sollen.>\n\n\"...als sehr schmale Kante feingeschliffen, kann das Material Schwächen aufweisen...\"\n\n\"wenn es auf diese Weise gegratet und poliert wird, wendet es schädliche...\"\n\n\"...eine unglaubliche Entdeckung, dass ein Kristall an die Vitalität des Trägers angepasst werden kann!\"", sourceObjective = "Testet die Effekte eines geschliffenen Kristalls, eines polierten Kristalls und eines harmonischen Kristalls in Aruuna aus.", progress = "Hm, was habt Ihr denn da für ein Buch?", completion = "Meine Notizen! In diesem Chaos habe ich sie ganz vergessen!\n\nDas ist mein Lebenswerk, {name}. Ich danke Euch vielmals.", sourceObjectiveStatus = "unverified-source-field" }
quests[33765] = { id = 33765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Feinde", description = "Eure Ankunft sollte ein Grund zum Feiern sein, doch fürchte ich, dass uns noch viel Ärger bevorsteht.\n\nKriegsherr Ner'zhul und sein Schattenmondklan haben einen Überraschungsangriff auf eine Draeneisiedlung im Norden durchgeführt.\n\nProphet Velen ist den Verwundeten beim Teluuna-Observatorium zu Hilfe geeilt, aber wir brauchen weitere Verteidiger.\n\nIch muss die anderen unterstützen. Falls Ihr uns zu helfen wünscht, geht nach Baumhain und tötet sämtliche Schattenmondangreifer, die Ihr zu Gesicht bekommt.", sourceObjective = "Tötet 8 Leerenwirker des Schattenmondklans.", completion = "Konntet Ihr den Wald vom Schattenmondklan befreien? Gut. Ich wusste, dass wir uns auf Euch verlassen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[33772] = { id = 33772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Invasion Opt-Out" }
quests[33782] = { id = 33782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrung des Gleichgewichts", description = "Seht Euch nur diese Zähne an. Diese Belastungsmuster lassen vermuten, dass die Krokilisken von einem ihrer eigenen Art unterworfen wurden. Wenn ein Krokiliskenweibchen groß genug wird, übernimmt es die Führung seiner Gruppe.\n\nEs ist meine Pflicht als Jäger, als Dank für ihr Opfer zugunsten meines Überlebens dafür zu sorgen, dass die Balance unter diesen Kreaturen wiederhergestellt wird.\n\nSpürt die Bestie auf und tötet sie, während ich meine Wunden versorge. Sie befindet sich wahrscheinlich am anderen Ende das Arbitums.", sourceObjective = "Tötet Schnappgriff im Arbitum.", sourceObjectiveStatus = "unverified-source-field" }
quests[33784] = { id = 33784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gormaulturm", description = "Es ist höchste Zeit, dass wir die bekämpfen, die uns versklaven wollen!\n\nWir ziehen zum Gormaulturm und werden die Speerspießeroger von dort vertreiben. Ich würde mich freuen, wenn Ihr uns begleitet.\n\nSteigt auf und wir reiten gemeinsam in die Schlacht!", sourceObjective = "Entreißt den Gormaulturm den Ogern der Speerspießer.", progress = "Ihr dürft Euch uns anschließen und mit unserem Rudel kämpfen.", completion = "Jetzt verstehe ich, wie Ihr meinen Klan aus den Klauen der Sklaverei befreien konntet! Ihr verfügt über mächtige Kräfte!", sourceObjectiveStatus = "unverified-source-field" }
quests[33785] = { id = 33785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entfesselte Karg", description = "Sie haben mir meine Brüder und Schwestern genommen.\n\nSie haben mir meinen Wolf genommen.\n\n<Karg hebt seine Axt und fixiert die Schneide mit seinem Blick.>\n\nJetzt nehmen wir ihnen ihre Köpfe.", sourceObjective = "Tötet 25 Orcs der Donnerfürsten in Grom'gar.", progress = "Indem wir sie töten... Wir nehmen ihre Köpfe, indem wir sie töten.\n\nWir müssen ihre Köpfe eigentlich nicht einmal mitnehmen.", completion = "<Karg greift sich eine Handvoll Schnee und säubert seine Axt von Blut.>\n\nIhr kämpft gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[33786] = { id = 33786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lahmgelegte Karawane", description = "Mich erreichen Berichte, dass die Botani begonnen haben, ihren Flor zu verlassen und wandernde Reisende anzugreifen. Das ist höchst ungewöhnlich.\n\nWir haben bereits einige Rangari entsandt, die versuchen sollen, diese Angelegenheit zu klären.\n\nEine Karawane aus Azeroth kam vor Kurzem hier vorbei. Ihr solltet vielleicht einmal nach Euren Leuten sehen, um sicherzugehen, dass es ihnen gut geht.", sourceObjective = "Sucht Fionas Karawane im Schattenmondtal.", completion = "Kommandant! Ich bin froh, Euch zu sehen.\n\nWir haben hier ein Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[33787] = { id = 33787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fionas Lösung", description = "Gidwin wurde von einem dieser Pflanzenwesen angegriffen.\n\nSo, wie es aussieht, leidet er an irgendeiner Form von Lähmung.\n\nIch kann ein Heilmittel herstellen, doch ich benötige dafür einige Zutaten aus der Gegend.", sourceObjective = "Sammelt 1 Flussbestienherz, 2 Einheiten Sumpfleuchtergift, 4 Kampfranken und 3 Bündel Mondlichtkraut im Schattenmondtal.", progress = "Habt Ihr die Zutaten?", completion = "Fantastische Arbeit, {name}! Die Grundlage ist fast fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[33788] = { id = 33788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen mit instabilen Kräutern", description = "Die Grundlage kocht und ist bereit für die anderen Zutaten.\n\nGebt die Zutaten eine nach der anderen hinein, ich werde mich dann um das Mischen und Aufschäumen kümmern. Sagt mir Bescheid, wenn Ihr so weit seid.", sourceObjective = "Helft Fiona, ein heilendes Elixier zu brauen.", completion = "Gidwin sieht schon viel besser aus. Vielen Dank, {name}.\n\nWir haben gerade noch genug Elixier übrig, um auch den anderen zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33793] = { id = 33793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorboten der Leere", description = "Unsere Späher haben eine entsetzliche Entdeckung gemacht, {name}.\n\nDie Seelen der Gefangenen werden dazu verwendet, um Kreaturen aus der Leere zu beschwören.\n\nIm Innern warten bereits drei Bestien der Finsternis: die Essenz der Schatten, die Essenz der Finsternis und die Essenz der Pein.\n\nSie müssen sofort vernichtet werden, bevor ihre Macht entfesselt werden kann.", sourceObjective = "Vernichtet die Essenz der Schatten, die Essenz der Finsternis und die Essenz der Pein.", completion = "Ich wusste, dass ich Euch mit dieser Aufgabe betrauen kann, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33794] = { id = 33794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Erlösung", description = "Wir haben die Gefangenen gefunden. Sie werden hier in der Schattenmondfestung festgehalten.\n\nRettet bitte so viele der Gefangenen, wie Ihr könnt. Und beeilt Euch. Wir können hier draußen ihre Schreie hören.", sourceObjective = "Befreit 8 gefangene Draenei aus ihren Käfigen.", completion = "Wir kümmern uns jetzt um die Überlebenden. Ihr habt ihnen ihr Leben gerettet. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33795] = { id = 33795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwischen den Sternen", description = "Ein wichtiger Teil der Macht des Schattenmondklans basiert auf ihrem Wissen über die Sterne und ihre Omen.\n\nSeit Jahrhunderten zeichnen sie bereits die Muster der Sterne und ihre Interpretationen auf.\n\nSammelt doch bitte einige dieser Dokumente für mich, wenn Ihr in der Festung seid.\n\nWir werden ihr eigenes Wissen gegen sie verwenden.", sourceObjective = "Sammelt 5 Sternkarten.", progress = "Wir sind für Eure Hilfe sehr dankbar, {class}.", completion = "Vielen Dank. Meine Akolythen werden diese in allen Einzelheiten studieren. Wenn wir Glück haben, werden wir dieses Wissen dazu nutzen können, um den Schattenmondklan zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33800] = { id = 33800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darren's Bombing Run of Awesomeness" }
quests[33807] = { id = 33807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für unsere Brüder und Schwestern", description = "Diese Hundesöhne von Donnerfürsten verwenden Netze und Ketten – Waffen für Feiglinge.\n\nViele der Dorfbewohner und unserer Wolfsbrüder und -schwestern wurden gefangen.\n\nWenn Ihr sie befreit, werden sie ehrenhaft an Eurer Seite kämpfen.\n\nWir müssen diesen Angriff schleunigst zurückschlagen, damit ich zur Speerspießerfestung zurückkehren und meine Vorbereitungen fortsetzen kann.", sourceObjective = "Befreit 6 Frostwölfe oder Einwohner von Wor'gol.", progress = "Es gibt noch immer weitere zu befreien, {class}.", completion = "Die Frostwölfe können nicht wie Tiere gefangen gehalten werden.\n\nIhr kämpft ehrenhaft, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33808] = { id = 33808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sumpfleuchterkönigin", description = "Sieht ganz danach aus, als ob diese Pflanzenkreaturen irgendein Gift verwendet haben, als sie Gidwin angriffen.\n\nEin ziemlich potentes Gemisch, das muss man ihnen lassen.\n\nWenn wir Gidwin retten wollen, benötigen wir einen zusätzlichen, besonderen Wirkstoff. Das Beschaffen dieses Stoffes wird wahrscheinlich etwas schwieriger ausfallen als bei den anderen.\n\nSeid Ihr der Aufgabe gewachsen, {name}?", sourceObjective = "Beschafft den Schwanz der Sumpfleuchterkönigin für Fiona im Schattenmondtal.", progress = "Ich wollte doch nur ein paar Kräuter sammeln und mich mit meinen Jungs entspannen... Ich hätte in Azeroth bleiben sollen.", completion = "Oh, das war schnell! Gut, fangen wir an!", sourceObjectiveStatus = "unverified-source-field" }
quests[33813] = { id = 33813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden gesucht", description = "Ich...<schluchz>... gehe hier nicht weg...<schluck>... ohne... Squiggy...!\n\nEr... Er... ist gefangen!\n\nIhr müsst... das Feuer... löschen!\n\n<Ariaana zeigt auf die andere Seite des Raums und bricht in Tränen aus.>", sourceObjective = "Rettet Squiggy, indem Ihr die Feuer mit Eimern voll Wasser löscht.", progress = "Squiggy... ist... mein... bester... Freund!", completion = "Ihr habt es geschafft! Squiggy geht es gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[33814] = { id = 33814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelle Expansion", description = "Seid gegrüßt, Kommandant!\n\nIch bin im Auftrag des Architekten Baros Alexston hier.\n\nWir haben genug Ressourcen für die nächste Ausbauphase gesammelt.\n\nAlexston möchte mit Euch sprechen, sobald Ihr Zeit habt.", sourceObjective = "Meldet Euch bei Baros Alexston in Eurer Garnison im Schattenmondtal.", completion = "Ah, willkommen, Kommandant! Genau die Person, mit der ich sprechen wollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[33815] = { id = 33815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Lied von Frost und Feuer", description = "Ihr habt viele meiner Klanmitglieder aus den Sklavenpferchen von Tanaan gerettet. Ihre Befreiung und die Zerstörung des Dunklen Portals sind mir Beweis genug, dass Ihr <einer/eine> von uns seid.\n\nAllerdings erachtet Euch unser Anführer, Durotan, immer noch als <Fremden/Fremde>. Lasst mich Euch ihm vorstellen.", sourceObjective = "Trefft Euch mit Durotan.", progress = "Ihr seid wahrlich ein seltsames Wesen.", completion = "Danke, dass Ihr meine Leute sicher zurückgebracht habt. Ich heiße Euch als Ehrengast willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33816] = { id = 33816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre wird belohnt", description = "Ihr habt meinem Volk alle Ehre erwiesen. Jetzt möchten wir Euch ehren.\n\nWir haben ein Aufnahmeritual für unseren Klan. Wenn jemand alt genug ist, bedeckt er sich mit dem Blut seiner ersten Jagdbeute und legt seine Hände auf einen Schamanenstein, um seine Vorfahren zu ehren.\n\nIn der kurzen Zeit, die wir miteinander verbracht haben, habt Ihr bereits viele Feinde niedergestreckt, die weitaus schlimmer waren als alle, die unseren Jägern je begegnet sind. Geht, berührt den Schamanenstein hier in Wor'gol und schließt Euch unserem Rudel als Gleichberechtigter an.", sourceObjective = "Geht zum Schamanenstein in Wor'gol und erhaltet Euren Segen.", completion = "Wenn Ihr unserem Klan weiterhin helfen wollt, werden die anderen Schamanensteine Eure Verbundenheit mit den Frostwölfen spüren und Euch vielleicht noch mit weiteren Gaben segnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33820] = { id = 33820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Zwielichtflur" }
quests[33823] = { id = 33823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Archaeology - Frostfire - Dig Map #1" }
quests[33824] = { id = 33824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Archaeology - Frostfire - Dig Map #2" }
quests[33825] = { id = 33825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Archaeology - Frostfire - Dig Map #3" }
quests[33826] = { id = 33826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist mein Wolf?!", description = "Mein Frostwolf Nerok wurde mit mir und den anderen gefangen genommen. Ich weiß nicht, wo sie ihn festhalten, aber ich wette, der sogenannte \"Bestienmeister\", der uns hierher geschleift hat, weiß es.\n\nEr prahlt hier ganz in der Nähe bei den Pferchen vor den jüngeren Jägern mit seinem Fang.\n\nMal sehen, wie sehr ihm mit meiner Axt im Schädel nach Prahlen zumute ist.", sourceObjective = "Tötet Bestienmeister Torash und befreit Nerok in Grom'gar.", completion = "Nerok und ich sind die einzigen überlebenden Gefangenen, aber wir können jetzt noch nicht gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33828] = { id = 33828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterbelagerungsschmied", description = "Vor nicht allzu langer Zeit war die fortschrittlichste Waffe, die ein Donnerfürst herstellen konnte, ein wirklich großer Speer. Die Schwarzfelsorcs müssen einen furchterregenden Meister herangeschafft haben, dass sie so schnell Kanonen produzieren können.\n\nWir müssen diesen Meister finden.", sourceObjective = "Tötet Meisterbelagerungsschmied Uratok in Grom'gar.", completion = "Die Eiserne Horde kombiniert die Stärken aller Klans. Wir müssen weiter nach Möglichkeiten suchen, diese Verbindung zu trennen, wenn wir sie besiegen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33833] = { id = 33833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kuu'rats Hauer", description = "Von: Eremor\n\nEine wilde Elekkkuh von außerordentlicher Größe wurde in der Nähe des Schummergehölzes gesichtet.\n\nEinige nennen sie den Weißen Tod, da sie ungewöhnlich aggressiv ist und bereits mehrere unachtsame Reisende das Leben gekostet hat.\n\nDie Rangari haben diese Kreatur noch nicht stellen können. Sollte jemand in der Lage sein, diese Bestie zu erlegen, dann kann er den Beweis für ihr Ableben bei Eremor am Teluuna-Observatorium gegen eine stolze Belohnung eintauschen.", sourceObjective = "Erschlagt Kuu'rat und bringt ihre Hauer zu Eremor in Embaari.", progress = "Seid Ihr wegen des Kopfgelds auf Kuu'rat hier?", completion = "Der Weiße Tod wurde erlegt? Beeindruckend, Reisender.\n\nDank Euch gehört Kuu'rat der Vergangenheit an und diese Lande sind wieder etwas sicherer. Ich werde den anderen Dorfbewohnern von Eurer Tat berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33834] = { id = 33834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kliaas Stachel", description = "Von: Dyuna\n\nEine wilde Sumpfleuchterkönigin hat sich in den nördlichen Wäldern des Schattenmondtals eingenistet.\n\nUnglücklicherweise terrorisiert dieses giftige Ungeziefer jetzt die Wälder zwischen Embaari und Shattrath. Dadurch müssen die hiesigen Händler regelmäßig ihr Leben aufs Spiel setzen, was zu einer dramatischen Verteuerung von Waren führen wird.\n\nWer auch immer der Bestie ein Ende setzen kann, soll ihren Stachel entfernen und ihn Dyuna in Embaari übergeben. Die Handelsleute des Orts haben eine fürstliche Belohnung ausgesetzt.", sourceObjective = "Tötet Kliaa und bringt ihren Stachel zu Dyuna in Embaari.", progress = "Man erzählt sich, dass Ihr Jagd macht auf Kliaa. Habt Ihr schon was erreicht?", completion = "Bei den Ältesten von Karabor... dieses Ding ist riesig!\n\nUnsere Handelswege sind wieder sicher. Nun ja... so sicher, wie ein Spießrutenlauf durch die nördlichen Wälder eben sein kann.\n\nGut gemacht, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[33836] = { id = 33836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Maa'runs Huf", description = "Von: Orrin\n\nEin wilder Talbuk namens \"Maa'run\" durchstreift die Hügel südöstlich von Embaari und westlich des Draakoriums.\n\nMein Bruder wurde von dieser elenden Bestie angefallen und schwer verletzt.\n\nUm die Sicherheit der umliegenden Dörfer zu gewährleisten, müssen wir dem Treiben dieser tollwütigen Kreatur ein Ende setzen!\n\nEine stattliche Belohnung wird demjenigen ausgehändigt, der den Huf des Talbuks als Beweis seines Ablebens vorweisen kann.", sourceObjective = "Beschafft Maa'runs Huf.", progress = "Mein Bruder Anduur sammelt regelmäßig Wildbeeren in den Hügeln nördlich des Dorfes.\n\nDabei kam es kürzlich zu dem unglückseligen Zusammenstoß mit Maa'run.\n\nIch verlange Vergeltung für seine Wunden.", completion = "Habt Dank, Abenteurer! Jetzt können wir wieder ruhig schlafen in dem Wissen, dass diese Bestie ihr Ende gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[33837] = { id = 33837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelheit kommt", description = "Es beginnt. Hinter den Hügeln im Südosten.\n\nNer'zhul verfügt nun über alles, was er benötigt, um den dunklen Stern zu beschwören. Der Angriff der Eisernen Horde auf Karabor steht kurz bevor. Hier wird die Entscheidung fallen.\n\nChampion, ich muss Euch bitten, vorauszureiten und Ner'zhul hinzuhalten. Ich werde so schnell wie möglich zu Euch stoßen.", sourceObjective = "Sucht Ner'zhul.", completion = "Prophet Velen ist tot. Und doch haben wir keine Zeit zum Trauern.\n\nWir werden Velen die letzten Ehren erweisen, wenn wir die Eiserne Horde endlich aus diesen Hügeln vertrieben haben.\n\nAber jetzt ist erst einmal die Zeit zum Kämpfen, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[33838] = { id = 33838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhüttung", description = "<Fremder/Fremde>! Den Geistern sei Dank, dass sie Euch geschickt haben. Ich bin gerade dabei, eine Klinge zu schmieden, und kann sie in diesem heiklen Zustand nicht liegen lassen. Ich brauche noch etwas Erz, um die Arbeit zu Ende zu bringen.\n\nHier, nehmt meine Spitzhacke. Sie wurde aus den Zähnen und der Säure der Goren aus dieser Gegend gefertigt und kann das Erz hier durchtrennen wie ein heißes Messer die Butter.\n\nBringt mir bitte das Erz. Dann werde ich Euch diese Klinge zur Verfügung stellen.", sourceObjective = "Benutzt Na'Shras Spitzhacke, um 20 Fomoriumerz zu sammeln.", progress = "Die Macht einer Waffe beruht auf dem verwendeten Metall und der Fertigkeit der Hand, die sie führt.", completion = "Das ist der perfekte Zeitpunkt. Der Stahl der Klinge ist immer noch formbar. Noch ein paar Schläge, und meine Arbeit ist beendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[33839] = { id = 33839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Naaru Purified" }
quests[33843] = { id = 33843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnatürliche Auslese", description = "Goren sind gefährlich, besonders in großer Zahl... und erst recht, wenn wir einen blinden, ausgelaugten Schamanen bei uns haben.\n\nGlücklicherweise leben Goren nicht sehr lange. Unglücklicherweise vermehren sie sich aber schnell und wachsen noch schneller.\n\nWenn wir das hier schaffen wollen, müssen wir ihre Brutmutter finden. Wenn wir sie töten und ihre Eier vernichten, sollte das den Ansturm der Goren bremsen. Überprüft die Löcher in der Nähe des Tors zur Schmiede, ich werde sie solange von Drek'Thars Fährte ablenken." }
quests[33846] = { id = 33846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flag: Seen Thrall Cyclone" }
quests[33847] = { id = 33847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flag: Seen Ga'nar Rolling Out" }
quests[33866] = { id = 33866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Veemas Kräuterbeutel" }
quests[33867] = { id = 33867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Kiste des Sterndeuters" }
quests[33868] = { id = 33868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heimat der Frostwölfe", description = "Ihr habt den Frostfeuergrat erreicht. Scharfseher Drek'Thar kann Euch von hier an führen.", sourceObjective = "Sprecht mit Drek'Thar an der Absturzstelle im Frostfeuergrat.", completion = "<Der Schamane wirft einen grinsenden Blick zu der rauhen, windgepeitschten Küste.>\n\nWillkommen in der Heimat meines Volkes, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33869] = { id = 33869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Elekkhorn" }
quests[33871] = { id = 33871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Seherin", description = "Wir beobachten Euch seit einiger Zeit.\n\nSeherin Malune, die Hüterin der Erinnerungen, hat um eine Audienz mit Euch gebeten, <Abenteurer/Abenteurerin>.\n\nSie hat schon vor langer Zeit die Ankunft <eines großen Helden/einer großen Heldin> vorhergesagt, <der/die> den lauernden Schatten vernichten würde. Wir glauben, dass Ihr <dieser Held/diese Heldin> seid.\n\nKommt zur Abendlichtinsel, unweit von hier im Süden, und erfüllt Eure Bestimmung.", sourceObjective = "Sprecht mit Seherin Malune auf der Abendlichtinsel in Talador.", completion = "Ich bin Seherin Malune, die große Hüterin der Erinnerungen. Es ist mir eine Ehre, Euch endlich zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33872] = { id = 33872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staub der Toten", description = "Ich dachte, wenn ich ihn nur hierher brächte, dann könnte ich seine Verfehlung gegenüber dem Licht ungeschehen machen. Dann könnte ich meinen Sohn vielleicht retten! Doch jetzt ist mein geliebter Arumel nichts anderes als ein verzerrtes Trugbild.\n\nJetzt bleibt mir nicht anderes, als meine Fehler wiedergutzumachen, und dafür brauche ich Eure Hilfe.\n\nBringt mir bitte etwas Dämmerschwingenstaub von den Motten der Abendlichtinsel. Mit Eurer Hilfe braue ich ein Elixier, das uns erlauben wird, ins Reich der Toten zu reisen und Arumel zur letzten Ruhe zu betten.", sourceObjective = "Sammelt 7 Handvoll Dämmerschwingenstaub von den Dämmerschwingenmotten auf der Abendlichtinsel.", progress = "Habt Ihr genug Staub gefunden?", completion = "Habt Dank, {name}. Mit diesem Staub und den Aruunembeeren werde ich nun das Gebräu des Todes mischen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33873] = { id = 33873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aruunem-Heilmittel", description = "Ich brauche Eure Hilfe, ein Elixier zu mischen, mit dem wir uns ins Reich der Toten wagen können.\n\nDazu benötige ich ein paar Früchte aus der näheren Umgebung. Ihr könnt Aruunembeeren überall auf der Insel finden. Bringt mir so viele davon, wie Ihr tragen könnt.\n\nDoch seid gewarnt, {name}: esst sie auf keinen Fall roh. Das Gift der Beeren wirkt schnell und tödlich!", sourceObjective = "Sammelt auf der Abendlichtinsel 60 Aruunembeeren.", progress = "Habt Ihr schon genügend Aruunembeeren gesammelt?", completion = "Ich bin froh, dass Ihr nicht von den Beeren gegessen habt. Ich weiß nicht, was ich tun würde, wenn Ihr sterben würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[33874] = { id = 33874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aruumels Ruh", description = "Meine Aufgabe ist zu sehen, was andere nicht sehen können. Ich bewahre die Erinnerungen anderer und gebe sie für sie wieder, doch aufgrund meines Sohnes kann ich das nicht mehr.\n\nMein Sohn hat sich vom Licht abgewandt. Als er verschied, war mir der Gedanke unerträglich, dass sein Geist in Auchindoun nicht willkommen sein könnte.\n\nAlso griff ich ein und sperrte ihn hier ein. Er verzerrt und quält die Erinnerungen bis zur Unlesbarkeit.\n\nIhr müsst das vollbringen, was ich nicht konnte. Verwendet dieses Elixier und dringt in das Geisterreich vor...\n\n... und vernichtet den Geist meines Sohnes.", sourceObjective = "Betretet das Geisterreich und vernichtet die Erinnerung an Arumel.", completion = "Manche Erinnerungen bleiben besser für immer vergessen. Vielen Dank, {name}.\n\nIch werde Euch in unsere Welt zurückbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33882] = { id = 33882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küken in Panik", description = "Dieser gemeine alte Sher'khaan! Er war schon immer fies zu den Pfauenküken, aber dieses Mal ist er zu weit gegangen!\n\nIch wollte gerade diese arme Schar Pfauenküken vor den Dämonen in Sicherheit bringen, als er plötzlich angriffen hat. Und jetzt haben die Küken Angst und sind in alle Richtungen davongelaufen!\n\nBitte helft mir, sie alle zurückzubringen.", sourceObjective = "Rettet 7 verängstigte Pfauenküken und bringt sie zu Caleb zurück.", completion = "Oh, ich danke Euch! Jetzt kann ich diese kleinen Pfauenküken endlich in Sicherheit bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33883] = { id = 33883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schattenmondschatzkiste Nr. 2" }
quests[33884] = { id = 33884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sher'KHAAAAAAANNNN!", description = "Die Tiger hier sind total außer Rand und Band! Sie laufen hier durch die ganze Gegend und sind so gemein wie noch nie.\n\nSher'khaan ist der Schlimmste von ihnen. Er ist riesengroß und böse! Vielleicht könnte <ein tapferer Abenteurer/eine tapfere Abenteurerin> wie Ihr ja Sher'khaan und die anderen Tiger ein für alle Mal wegmachen.", sourceObjective = "Tötet 8 Scharfzahnpirscher und besiegt Sher'khaan.", completion = "Ihr seid unglaublich mutig! Ich hätte Sher'khaan niemals alleine töten können.\n\nJetzt machen mir nur noch die gruseligen Orcs Angst... und die Riesenvögel, die Nilpferde, die großen Vogelmenschen, die Spinnen und das ganze Feuer...\n\nHm... Vielleicht wäre ich besser nicht allein hier draußen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33885] = { id = 33885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Hafenschatz" }
quests[33886] = { id = 33886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Ronokks Habseligkeiten" }
quests[33887] = { id = 33887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Mini-Kriegsmaschine A" }
quests[33888] = { id = 33888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Mini-Kriegsmaschine B" }
