quests[33890] = { id = 33890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Mini-Kriegsmaschine D" }
quests[33891] = { id = 33891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Mondweidensamen" }
quests[33898] = { id = 33898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertreibung der Sklaventreiber", description = "Die Oger nehmen immer wieder Mitglieder meines Klans gefangen und versklaven sie!\n\nTötet ein paar Oger. Ich werde sie aufhalten, wenn sie versuchen, zu entkommen.", sourceObjective = "Tötet 12 Oger im Rußgeschwärzten Bergbaulager.", completion = "In Euch brennt wahrlich das Feuer.", sourceObjectiveStatus = "unverified-source-field" }
quests[33899] = { id = 33899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Turn on the Holograms" }
