quests[33903] = { id = 33903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Activated Arkonite 5" }
quests[33905] = { id = 33905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tür zu!", description = "Die Schattenmondorcs verwenden Portale, um Verstärkung hereinzubringen und gefangene Draenei fortzuschaffen.\n\nWenn wir das Dorf zurückerobern wollen, müssen wir unverzüglich diese Portale zerstören.\n\nUnd dazu müssen wir die Portalmeister töten, die die Risse offen halten.", sourceObjective = "Schließt 3 Leerenportale, indem Ihr die Portalmeister des Schattenmondklans tötet.", completion = "Wunderbar. Das sollte dem Angriff etwas Einhalt gebieten.\n\nUnsere Truppen sollten jetzt in der Lage sein, den Wald umgehend zurückzuerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[33909] = { id = 33909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markierung: Ga'nar ist zur Speerspießerfestung aufgebrochen" }
quests[33910] = { id = 33910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aklanas Rettung" }
quests[33914] = { id = 33914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Guttra", description = "Der Hunger von Guttra Wolfsbiss ist für dieses Massaker verantwortlich. Er wird für das Blut, das er heute vergossen hat, mit dem Leben bezahlen.\n\nIhr könnt Guttra oben auf dem Grimmfrostberg im Norden finden. Erschlagt ihn und kehrt dann zu mir zurück.\n\nWenn Ihr wieder hier seid, werden wir Euren Sieg begießen.", sourceObjective = "Tötet Guttra Wolfsbiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[33915] = { id = 33915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junge Herzen", description = "Mein Neffe achtet nie auf seine Umgebung. Er will sich immer beweisen und hat sich mal wieder viel zu weit vom Rudel entfernt.\n\nEr erinnert mich an mich selbst, als ich noch jung war.\n\nWenn Ihr Orac seht, dann sagt ihm, dass er nach Hause kommen soll. Wir müssen noch Vorbereitungen für die Jagd morgen treffen.", sourceObjective = "Findet Orac und sagt ihm, dass er zu seinem Onkel nach Hause zurückkehren soll.", completion = "Ich danke Euch, {name}. Ich bin mir sicher, dass sich Orac in Zukunft nicht mehr so unüberlegt vom Rudel entfernen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[33916] = { id = 33916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Kriegshorn des Arenameisters" }
quests[33917] = { id = 33917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub unterbrechen", description = "He, Ihr da! Wir müssen unbedingt die Verstärkung der Dämonen aufhalten!\n\nSeht Ihr die überall an der Front schwebenden Teufelskristalle? Diese Resonatoren versorgen die Portale mit Energie und bringen unsere Truppen in höchste Bedrängnis. Ich will, dass Ihr sie ausschaltet!", sourceObjective = "Zerstört 4 Brennende Resonatoren an der Brennenden Front.", completion = "Ab jetzt kommen wir wieder allein klar. Möge das Licht Euch segnen, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[33918] = { id = 33918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kopfgeld für Grondo", description = "Grondo, ein wahnsinniger Gronn, wurde beim Durchstreifen der Knirschenden Ebenen gesichtet.\n\nDiese Bestie hat ganze Grollhufherden getötet und unschuldige Frostwölfe verschlungen. Wir müssen diese Bedrohung vernichten, bevor sie die Garnison erreicht.", sourceObjective = "Tötet Grondo auf den Knirschenden Ebenen.", completion = "Sehr gut. Es wäre nicht gut, wenn ein Gronn uns angreift, bevor unsere Verteidigungsanlagen fertiggestellt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[33919] = { id = 33919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Darmquetsch der Zerstörer", description = "Darmquetsch hat sich schon unzählige Male als harter Gegner erwiesen. Sammelt einen kleinen Trupp zusammen und beendet ein für alle Mal seine Schreckensherrschaft.", sourceObjective = "Tötet Darmquetsch den Zerstörer im Frostfeuergrat.", completion = "Darmquetsch ist tot? Darauf trinke ich einen. Ihr seid in Ordnung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33920] = { id = 33920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz von Auchindoun", description = "Eine Bande Schattenratorcs hat das Herz von Auchindoun gestohlen!\n\nDas Herz versorgt die gesamte Verteidigung Auchindouns mit Energie. Zum Glück konnten wir den Kern und einen der vier Teile vor ihnen sichern.\n\nDer Hexenmeister O'mogg Schwarzherz verwendet Karab'uun, einen der gestohlenen Teile, um das größte Portal an der Brennenden Front mit Energie zu versorgen. Bringt Karab'uun zu mir zurück.", sourceObjective = "Besiegt O'mogg Schwarzherz und sichert Karab'uun an der Brennenden Front.", progress = "Ich hoffe, Ihr habt Karab'uun dabei. Wenn die unzähligen Seelen in Auchindoun in Gefahr sind, ist meine Geduld nur sehr begrenzt.", completion = "<Seelenbinderin Nyami zeigt ihr schönstes Lächeln.>\n\nGut gemacht. Jetzt bleiben nur noch zwei Teile. Ich habe schon meine Seelenbinder entsandt, um nach ihnen zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33923] = { id = 33923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen? In Auchindoun?", description = "Dämonen! Das hatte ich befürchtet.\n\nWir dürfen nicht zulassen, dass sie das Grab verlassen. Sie dürfen sich auf keinen Fall Auchindoun nähern!\n\nSchnell, geht hinein und deaktiviert das Portal, durch das sie kommen. Ich werde in der Zwischenzeit die Verteidigung der Auchenai organisieren. Das Portal wird mit Sicherheit von einem mächtigen Hexenmeister offen gehalten. Wenn Ihr ihn tötet, wird das Portal zusammenbrechen!", sourceObjective = "Tötet O'mogg Schwarzherz im Grab des Lichts, um das Dämonenportal zu schließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33925] = { id = 33925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Frostwolf Cache 01" }
quests[33926] = { id = 33926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Lagunenteich" }
quests[33927] = { id = 33927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenei Camp Explosion Tracker" }
quests[33928] = { id = 33928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leid von Erd und Feuer", description = "Bei dem geschmolzenen Kern scheint es sich um die mutierten Überreste eines Elementars zu handeln, der sowohl aus Erde als auch aus Feuer bestanden hat.\n\nSchlackeelementare sollten auf dem Plateau, auf dem die Elementare in Reinheit leben, nicht vorkommen.\n\nDer Kern sollte zur Untersuchung zu Incineratus beim Thron der Elemente gebracht werden.\n\nVielleicht weiß der große Zorn des Feuers, was er von diesem Kern und Eurem Kampf gegen Magmorast, halten soll.", sourceObjective = "Bringt den geschmolzenen Kern zu Incineratus.", completion = "<Incineratus untersucht den Kern, während Ihr die Umstände seiner Beschaffung erläutert.>\n\nTatsächlich... Schlackeelementare sollten auf dem Plateau nicht vorkommen. Das Plateau ist instabil geworden und sorgt dafür, dass sich die Elementargeister zurückentwickeln und mutieren.\n\nSolange kein Erdzorn den Thron besteigt, wird das Ungleichgewicht der Elemente immer schlimmer werden.\n\nGordawg muss zum Thron der Elemente zurückkehren, wenn das Gleichgewicht wiedergewonnen werden soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[33929] = { id = 33929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zitterfells Höhle", description = "Der Frostwolfwelpe schaut Euch mit großen Augen an. Er jault und starrt in die Höhle.\n\nFür einen so jungen Wolf ist es eher ungewöhnlich, allein durch die Gegend zu streifen. Zitterfells Eltern müssen ganz in der Nähe sein.", sourceObjective = "Sucht nach Zitterfells Eltern im Frostfeuergrat.", completion = "Zitterfell kuschelt sich an seine Mutter. Er ist ganz offensichtlich glücklich, wieder mit dem Großteil seines Rudels vereint zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[33930] = { id = 33930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Saberonvorrat" }
