quests[33940] = { id = 33940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Klippenspringertruhe" }
quests[33942] = { id = 33942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Frostwolf Cache 02" }
quests[33944] = { id = 33944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sogar den Elekk?!", description = "Der kleine Plüschelekk hat schon bessere Zeiten gesehen. Er ist aufgerissen und seine Füllung quillt heraus.\n\nAuf der Unterseite des hinteren linken Fußes ist der Name Caleb eingestickt. Sher'khaan muss ihn sich von dem Wagen geschnappt haben. Der kleine Draenei wird sich sicher freuen, ihn zurückzubekommen.", sourceObjective = "Bringt Ricky beim umgekippten Wagen zu Caleb zurück.", progress = "Wo habt Ihr Ricky gefunden?!", completion = "Danke! Ich kann nicht glauben, dass Sher'khaan sich sogar den Ricky geschnappt hat!\n\nIhr seid mein Held!", sourceObjectiveStatus = "unverified-source-field" }
quests[33945] = { id = 33945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Frostwolf Cache 03" }
quests[33946] = { id = 33946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Frostwolf Cache 04" }
quests[33947] = { id = 33947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Grimmfrosttruhe" }
