quests[33949] = { id = 33949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Frostwolf Cache 07" }
quests[33955] = { id = 33955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verschwundene Rudel", description = "Seltsam... Ich frage mich, wo Zitterfell und sein Rudel stecken? Normalerweise sind sie jetzt zur Fütterungszeit immer hier.\n\nIch hoffe, sie stecken nicht in Schwierigkeiten.", sourceObjective = "Findet Zitterfell nahe Wor'gol im Frostfeuergrat.", completion = "Ihr habt den kleinen Welpen erschreckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[33957] = { id = 33957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Raa'la", description = "Ich muss diese Beute hier einpacken. Ich habe meiner Tochter, Raa'la, versprochen, ihr etwas von der Jagd mitzubringen.\n\nIn der Höhle in der Nähe befinden sich ein paar Babyrylaks. Vielleicht möchte Raa'la ja einen als Haustier haben?\n\nWäret Ihr vielleicht so nett, mir einen zu fangen, während ich hier alles fertig mache?", sourceObjective = "Fangt einen Babyrylak für Raa'la im Scherwindtiefland.", sourceObjectiveStatus = "unverified-source-field" }
quests[33958] = { id = 33958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Höhle", description = "Ich habe erfahren, dass der Schattenrat das Gift der Todesnetzspinnen in der Nähe benutzt, um teuflische Verderbnis zu verbreiten und ihre Streitkräfte nach ihrer Niederlage an der Brennenden Front zu verstärken.\n\nEiner meiner Seelenbinder hat einen Schreckenslord dabei beobachtet, wie er sich mit Sha'tari, einem der verbleibenden Teile des Herzens von Auchindoun, in die Minen im Osten aufmachte.\n\nIhr müsst Sha'tari dem zuckenden Leichnam des Schreckenslords entreißen und es mir bringen, Champion.", sourceObjective = "Tötet Xanatos den Entweiher in der Todesnetzhöhle und bergt Sha'tari.", progress = "Hatte der Dämon wie vermutet Sha'tari?", completion = "Genau wie erwartet. Ich danke Euch, {name}. Jetzt wo Sha'tari wieder in unserem Besitz ist, müssen wir nur noch den letzten Teil des Herzens holen.", sourceObjectiveStatus = "unverified-source-field" }
